// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · AYT Sosyal-1 karma: edebiyat dönem karşılaştırması, tarihsel kanıt yorumlama ve coğrafi nedensellik soruları (kolay).
const ozExam17Kolay = <(String, String, List<String>, String)>[
  ('"Gönül aynasını sildim pasından / Geçtim bu dünyanın kuru yasından" dizeleri ile "Mir\'ât-ı kalbi kıldım ise jengden halâs / Gam-hâne-i cihândan eder cânımız firâr" beyti karşılaştırıldığında bu iki metni ayıran temel unsur aşağıdakilerden hangisidir?', 'Dil, ölçü ve nazım birimi tercihi', ['İşlenen tasavvufi öz ve dünyadan arınma teması', 'Şairin içsel arınmayı somutlaştırma kaygısı', 'Maddi dünyaya duyulan mesafeli yaklaşım biçimi'], 'İlk metin Halk şiirine özgü sade dil, hece ölçüsü ve dörtlük/ikilik duyarlılığı taşırken ikinci metin Divan şiirine özgü ağır dil, aruz ve beyit birimiyle kurulmuştur.'),
  ('Tanzimat I. Dönem şiirinde "hak, adalet, hürriyet, vatan" gibi kavramlar divan nazım biçimleri içinde işlenmiştir. Bu durumu en iyi özetleyen eleştirel yargı aşağıdakilerden hangisidir?', 'Eski biçimlerle yeni ve toplumsal özün birleştirilmesi', ['Biçimde köklü yenilik yapılırken eski temaların korunması', 'Halk şiiri nazım biçimleriyle bireysel konuların işlenmesi', 'Ölçü ve uyak kurallarının bütünüyle ortadan kaldırılması'], 'Şinasi ve Namık Kemal kuşağı kaside, gazel gibi eski biçimleri koruyup içeriği toplumsal-siyasal kavramlarla yenilemiştir.'),
  ('"Sanat, şahsi ve muhteremdir." ilkesini benimseyen Fecriati topluluğu ile "Milli bir edebiyat milli dille yaratılır." görüşünü savunan Genç Kalemler hareketi arasındaki en belirgin ayrım hangi alanda görülür?', 'Sanatın amacı ve yazı dilinin sadeleşmesi', ['Roman türünde teknik kusursuzluk arayışı', 'Tiyatronun halkı eğitmede tek araç sayılması', 'Divan edebiyatı mazmunlarının aynen sürdürülmesi'], 'Fecriati bireysel ve kapalı sanat anlayışıyla ağır dili sürdürürken Genç Kalemler sade Türkçe ve ulusal kaynaklara yönelişi savunmuştur.'),
  ('Servetifünun şiirinde beyit hâkimiyetinin kırılıp anlamın dizelerden diğer dizelere taşması (anjambman) hangi sonucu doğurmuştur?', 'Şiirin düzyazıya yaklaşması ve nazmın nesre yaklaştırılması', ['Divan şiirindeki parça güzelliği anlayışının güçlenmesi', 'Halk şiirindeki yarım uyak ve redif düzenine dönülmesi', 'Şiirde ölçü ve ahengin bütünüyle gereksiz görülmesi'], 'Anlamın dize sonlarında tamamlanmayıp sonraki dizelere sarkması nazmı nesre yaklaştırmış ve bütün güzelliğini sağlamıştır.'),
  ('Millî Edebiyat Dönemi romanlarında mekân olarak İstanbul dışına, özellikle Anadolu\'ya yönelinmesinin temel nedeni aşağıdakilerden hangisidir?', 'Ulusal bilinci halka ve gerçek ülke coğrafyasına dayandırma isteği', ['Yazarların basım olanaklarını yalnızca taşra kentlerinde bulabilmesi', 'Batılı roman tekniğinin büyük şehir anlatılarına izin vermemesi', 'Divan edebiyatındaki mesnevi geleneğini kırsalda canlandırma çabası'], 'Millî Edebiyatçılar halka doğru ilkesiyle İstanbul aydınını Anadolu insanı ve Kurtuluş mücadelesi gerçekliğiyle buluşturmuştur.'),
  ('Âşık tarzı Halk şiirinde şairin son dörtlükte mahlasını (tapşırma) söylemesi, Divan şiirindeki hangi nazım birimi uygulamasıyla işlevce benzerlik gösterir?', 'Gazel ve kasidelerin makta beytinde mahlas kullanılmasıyla', ['Mesnevilerde her beytin kendi arasında uyaklanmasıyla', 'Müstezat biçiminde uzun dizelere kısa ziyadeler eklenmesiyle', 'Rubailerin tek dörtlükten oluşup felsefi öz taşımasıyla'], 'Halk şiirindeki tapşırma geleneği, Divan şiirinde gazel ve kasidenin son (makta) beytinde şairin mahlasını anmasıyla aynı imza işlevini görür.'),
  ('Yunus Emre\'nin ilahilerindeki "sehl-i mümteni" özelliği ile Sebk-i Hindi akımından etkilenen 17. yüzyıl Divan şairlerinin üslubu karşılaştırıldığında ne görülür?', 'Yunus\'ta yalın görünüşlü derinlik, Sebk-i Hindi\'de girift imge ve anlam kapalılığı', ['Her iki anlayışta da yabancı tamlamalardan tamamen arınmış öz Türkçe kullanımı', 'Yunus\'ta ağır felsefi terimler, Sebk-i Hindi\'de ise atasözlerine dayalı açık anlatım', 'Her ikisinde de somut doğa manzaralarının hiçbir mecaza başvurulmadan aktarımı'], 'Sehl-i mümteni kolay sanılan ama taklidi güç duru derinliktir; Sebk-i Hindi ise ince hayaller, ıstırap ve kapalı-yoğun mecazlarla örülüdür.'),
  ('Cumhuriyet Dönemi\'nde Nazım Hikmet\'in öncülük ettiği toplumcu gerçekçi şiirin biçimsel açıdan getirdiği en belirgin yenilik aşağıdakilerden hangisidir?', 'Basamaklı dizeler, serbest nazım ve hitabet tonuna dayalı dinamik ritim', ['Aruzun yalnızca kısa kalıplarıyla yazılan müstezat biçiminin canlandırılması', 'Dörtlük birimi ve on birli hece ölçüsünün şaşmaz bir kurala bağlanması', 'Uyak ve ses tekrarlarının şiirden hiçbir istisna bırakılmadan silinmesi'], 'Mayakovski ve fütürizmden etkilenen Nazım Hikmet; kırık/basamaklı dizeler, serbest nazım ve coşkulu seslenişlerle yeni bir biçim kurmuştur.'),
  ('Dinî-tasavvufi Halk şiirindeki "şathiye" türü ile Divan edebiyatındaki "hicviye" karşılaştırıldığında aşağıdakilerden hangisi doğru bir saptamadır?', 'Şathiye görünüşte alaycı sözlerle tasavvufi sırları, hicviye ise kişi ya da toplum yergisini işler', ['Her iki tür de ölen bir devlet büyüğünün ardından duyulan derin üzüntüyü dile getirir', 'Şathiye yalnızca aruzla ve beyitle, hicviye ise yalnızca heceyle ve dörtlükle yazılır', 'İki türün de temel amacı padişahın kazandığı askerî zaferleri abartılı biçimde övmektir'], 'Şathiyede inanç konularıyla şakalaşır gibi görünerek derin tasavvufi hakikatler anlatılır; hicviyede ise (Halk şiirindeki taşlama gibi) yergi amaçlanır.'),
  ('Divan edebiyatında "mesnevi" nazım biçiminin Servetifünun ve Tanzimat dönemlerinde yerini Batılı anlamda "roman ve hikâye"ye bırakmasının temel nedeni nedir?', 'Uzun olay örgüsünü işleme işlevini modern düzyazı türlerinin üstlenmesi', ['Mesnevilerin beş beyitten uzun yazılmasının kurallarca yasaklanmış olması', 'Tanzimat sanatçılarının manzum eser yazmayı bütünüyle bırakmış olmaları', 'Mesnevi biçiminde aşk ve kahramanlık konularının hiç işlenememiş olması'], 'Divan döneminde romanın işlevini gören olay anlatma aracı mesneviydi; Tanzimat\'la birlikte bu işlevi Batılı hikâye ve roman devralmıştır.'),
  ('Anonim Halk şiirindeki "mani" ile Divan şiirindeki "tuyuğ" karşılaştırıldığında bu iki nazım biçiminin ortak yönü aşağıdakilerden hangisidir?', 'Tek dörtlükten oluşmaları ve aaxa uyak düzenini sıkça kullanmaları', ['Yalnızca yedi heceli ve kesintisiz duraklı hece ölçüsüyle yazılmaları', 'Aruzun yalnız mefâîlün mefâîlün feûlün kalıbıyla oluşturulmaları', 'Sadece düğünlerde gelin ağlatmak amacıyla ezgiyle söylenmeleri'], 'Hem mani hem de Divan edebiyatına Türklerin kazandırdığı tuyuğ tek dörtlükten oluşur, aaxa uyak şeması ve cinas eğilimi gösterir.'),
  ('Tanzimat Dönemi\'nde Şemsettin Sami\'nin yazdığı "Taaşşuk-ı Talat ve Fitnat" ile Namık Kemal\'in yazdığı "İntibah" romanlarının Türk edebiyatı tarihindeki ortak önemi nedir?', 'Batılı anlamda yerli ve edebî roman türünün ilk öncü örnekleri olmaları', ['Psikolojik roman türünün ve bilinç akışı tekniğinin ilk yetkin ürünleri olmaları', 'Kurtuluş Savaşı yıllarındaki Anadolu direnişini konu edinen ilk eserler olmaları', 'Köy gerçeğini natüralist deneysel yöntemle inceleyen ilk romanlar olmaları'], 'Taaşşuk-ı Talat ve Fitnat ilk yerli roman, İntibah ise ilk edebî roman olarak Tanzimat\'ta Batılı roman türünün başlangıcını temsil eder.'),
  ('Servetifünun sanatçılarının "Yeni Zelanda\'ya gitme" ya da Manisa\'da bir çiftliğe çekilme hayalleri kurmalarının eserlerine yansıyan temel sonucu aşağıdakilerden hangisidir?', 'Hayal-hakikat çatışması ve dış dünyadan içe kapanış temalarının ağırlık kazanması', ['Anadolu köylüsünün tarım sorunlarını çözen gerçekçi romanların yazılması', 'Tarihteki büyük Osmanlı fetihlerini anlatan epik mesnevilerin çoğalması', 'Mizah ve toplumsal hiciv dergilerinin edebiyatın merkezine yerleşmesi'], 'II. Abdülhamit döneminin siyasi atmosferi ve sanatçıların mizaçları, Servetifünun\'da kaçış psikolojisini ve hayal-gerçek çatışmasını doğurmuştur.'),
  ('Millî Edebiyat akımının yayın organı olan Selanik merkezli "Genç Kalemler" dergisinde Ömer Seyfettin\'in yayımladığı "Yeni Lisan" makalesinde aşağıdakilerden hangisi savunulmamıştır?', 'Türkçedeki tüm Arapça ve Farsça kökenli kelimelerin istisnasız dilden atılması', ['Arapça ve Farsça dil bilgisi kurallarıyla yapılan tamlamaların terk edilmesi', 'Konuşma diline yerleşmiş yabancı kökenli kelimelerin Türkçeleşmiş sayılması', 'Yazı dilinde İstanbul Türkçesinin konuşma ses ve yapısının esas alınması'], 'Yeni Lisan hareketi tasfiyeciliğe karşı çıkmış; halkın benimsediği kelimelerin kalmasını, ancak yabancı tamlama ve çoğul kurallarının atılmasını savunmuştur.'),
  ('Divan edebiyatındaki "kaside" ile Tanzimat Dönemi\'nde Namık Kemal\'in yazdığı "Hürriyet Kasidesi" karşılaştırıldığında biçim ve içerik ilişkisi nasıl değişmiştir?', 'Klasik giriş bölümleri atılıp kişi övgüsü yerine soyut bir kavramın yüceltilmesi geçmiştir', ['Beyit birimi terk edilerek hece ölçüsüyle yazılan dörtlük düzenine geçilmiştir', 'Uyak örgüsü aa ba ca olmaktan çıkarılıp çapraz uyak sistemine dönüştürülmüştür', 'Ağır Osmanlıca tamlamalar tamamen bırakılıp arı bir öztürkçe kullanılmıştır'], 'Namık Kemal nesib, girizgâh gibi klasik kaside bölümlerini kaldırarak doğrudan hürriyet kavramını öven yeni içerikli bir kaside kurmuştur.'),
  ('Sait Faik Abasıyanık ve Memduh Şevket Esendal\'ın hikâyeciliğimizde yaygınlaştırdığı "durum (Çehov) hikâyesi", Ömer Seyfettin\'in temsil ettiği "olay (Maupassant) hikâyesi"nden hangi yönüyle ayrılır?', 'Merak ögesini ve çarpıcı sonu geri plana çekip yaşamdan sıradan bir kesit ve atmosfer sunmasıyla', ['Serim, düğüm ve çözüm bölümlerini kesin çizgilerle ayırıp beklenmedik bir sonla bitmesiyle', 'Kahramanlarını yalnızca tarihteki ünlü komutanlar ve olağanüstü kahramanlar arasından seçmesiyle', 'Toplumsal bir tezi kanıtlamak için uzun felsefi ve sosyolojik açıklamalara yer vermesiyle'], 'Olay hikâyesinde gerilim ve düğüm-çözüm esasken Çehov tarzı durum hikâyesinde günlük hayattan bir kesit, izlenim ve bitmemişlik duygusu öne çıkar.'),
  ('Halk edebiyatındaki "destan" (Âşık tarzı) ile İslamiyet öncesi "doğal destan" arasındaki en temel fark aşağıdakilerden hangisidir?', 'Âşık tarzı destanın yazarı belliyken ve on birli heceyle dörtlükler hâlinde yazılırken doğal destanın anonim olması', ['Doğal destanların yalnızca bireysel aşk acısını, âşık destanlarının ise yaratılış mitlerini anlatması', 'Âşık tarzı destanların aruz ölçüsü ve beyitle, doğal destanların ise serbest ölçüyle söylenmesi', 'Her iki türün de yalnızca saray kâtipleri tarafından Farsça olarak kaleme alınmış olması'], 'Kayıkçı Kul Mustafa\'nın Genç Osman Destanı gibi âşık destanları şairi belli koşma tipi manzumelerdir; Oğuz Kağan gibi doğal destanlar ise anonimdir.'),
  ('Tanzimat I. Dönem\'de Şinasi\'nin yazdığı "Şair Evlenmesi" adlı tiyatro eseri, kendisinden önceki geleneksel Türk tiyatrosundan (Karagöz, Orta Oyunu) hangi temel özelliğiyle ayrılır?', 'Doğaçlama (tuluat) yerine yazılı bir metne ve Batılı komedya kurgusuna dayanmasıyla', ['Görücü usulü evliliğin hiçbir sakıncası olmadığını kanıtlamaya çalışmasıyla', 'Yanlış anlaşılmalara ve tip komiğine dayalı güldürü unsurlarını tümüyle reddetmesiyle', 'Trajedi türünün üç birlik kuralına ve soylu kahraman şartına sıkı sıkıya uymasıyla'], 'Şair Evlenmesi, geleneksel orta oyunu tiplerinden yararlanmakla birlikte yazılı metne dayanan ilk Batılı yerli tiyatro eserimizdir.'),
  ('"Bülbül ne yatarsın Çukurova\'da / Eşin şahin kapmış kendi yuvada" dizeleriyle başlayan bir Halk şiiri ile "Gül gülşeni terk eyledi bülbül kafese düştü" diyen bir Divan beyti karşılaştırıldığında ne görülür?', 'Benzer gül-bülbül/eş ayrılığı motifinin farklı kültür ve dil kodlarıyla işlendiği', ['Her iki şairin de aynı aruz kalıbını ve yabancı tamlamaları kullandığı', 'Halk şairinin doğayı soyutladığı, Divan şairinin ise Çukurova\'yı gözlemlediği', 'İki metnin de toplumsal adaletsizliğe karşı halkı ayaklanmaya çağırdığı'], 'Halk ve Divan şiiri arasında kültür alışverişi vardır; ancak Halk şairi motifi Çukurova ve şahin gibi yerel-somut unsurlarla, Divan şairi gülşen mazmunuyla işler.'),
  ('Cumhuriyet\'in ilk yıllarında Faruk Nafiz Çamlıbel\'in yazdığı "Sanat" şiirindeki "Başka sanat bilmeyiz, karşımızda dururken / Yazılmamış bir destan gibi Anadolu\'muz" dizeleri hangi edebî topluluğun bildirisi niteliğindedir?', 'Beş Hececiler (Memleket Edebiyatı)', ['Yedi Meşaleciler', 'Garipçiler (Birinci Yeni)', 'Maviciler'], 'Faruk Nafiz\'in "Sanat" şiiri, Batı taklitçiliğine karşı Anadolu\'yu ve halk sanatını kaynak alan Beş Hececiler/Memleket Edebiyatı anlayışının poetikasıdır.'),
  ('Divan edebiyatında "sefahat, şarap ve dünya zevklerini" tasavvuf dışı bir neşeyle işleyen Nedim ile "hikmetli söz söyleme ve toplumsal öğüt verme" yolunu açan Nabi karşılaştırıldığında hangi iki akım eşleşir?', 'Nedim: Mahallileşme - Nabi: Hikemi (Didaktik) Tarz', ['Nedim: Sebk-i Hindi - Nabi: Türki-i Basit', 'Nedim: Tasavvufi Tarz - Nabi: Parnasizm', 'Nedim: Klasisizm - Nabi: Romantizm'], '18. yüzyılda Nedim İstanbul Türkçesi ve günlük eğlenceyle Mahallileşme akımını, 17. yüzyılda Nabi ise düşünce ve atasözü ağırlıklı Hikemi tarzı temsil etmiştir.'),
  ('Cumhuriyet Dönemi\'nde "Garip" adını taşıyan 1941 tarihli ortak şiir kitabını yayımlayarak Türk şiirinde büyük bir kırılma yaratan üç şair aşağıdakilerden hangisinde doğru verilmiştir?', 'Orhan Veli Kanık - Oktay Rifat Horozcu - Melih Cevdet Anday', ['Cemal Süreya - Edip Cansever - Turgut Uyar', 'Faruk Nafiz Çamlıbel - Enis Behiç Koryürek - Yusuf Ziya Ortaç', 'Ziya Osman Saba - Yaşar Nabi Nayır - Vasfi Mahir Kocatürk'], 'Garip (I. Yeni) hareketi Orhan Veli, Oktay Rifat ve Melih Cevdet (OMO) tarafından 1941\'de yayımlanan ortak kitap ve önsözle başlatılmıştır.'),
  ('Dinî-tasavvufi Türk edebiyatında "Allah\'tan gelip tekrar Allah\'a dönme (devir kuramı)" inancını işleyen şiirlere ne ad verilir?', 'Devriye', ['Nutuk', 'Nefes', 'Methiye'], 'Varlığın İlahi kaynaktan çıkıp maddi âleme inişini (kavs-i nüzul) ve insan-ı kâmil olarak tekrar Allah\'a yükselişini (kavs-i uruc) anlatan şiirlere devriye denir.'),
  ('Divan şiirinde beş mesneviden oluşan eserler bütününe verilen ad aşağıdakilerden hangisidir?', 'Hamse', ['Divançe', 'Münşeat', 'Tezkire'], 'Arapça "beş" kökünden gelen hamse; Ali Şir Nevai, Taşlıcalı Yahya, Nevizade Atayi gibi şairlerin beş mesnevisini bir araya getiren külliyattır.'),
  ('Servetifünun Dönemi\'nde Tevfik Fikret\'in çocuklar için yazdığı "Şermin" adlı şiir kitabını onun diğer tüm şiirlerinden ayıran biçimsel özellik nedir?', 'Aruz yerine hece ölçüsüyle ve oldukça sade bir Türkçeyle yazılmış olması', ['Tamamının klasik kaside ve gazel nazım biçimleriyle kaleme alınması', 'Fransız sembolistlerinden çevrilmiş sone ve terzarimalardan oluşması', 'Ağır Arapça-Farsça tamlamalarla yüklü mensur şiir parçalarını içermesi'], 'Tevfik Fikret tüm olgunluk dönemi şiirlerinde aruzu kullanmış, yalnızca yaşamının son döneminde çocuklar için yazdığı Şermin\'de hece ölçüsünü seçmiştir.'),
  ('Millî Edebiyat Dönemi\'nde "Türkçülük" düşüncesini sistemleştiren ve "Kızıl Elma, Yeni Hayat, Altın Işık" adlı eserleriyle edebiyatçılara yön veren fikir ve sanat adamı kimdir?', 'Ziya Gökalp', ['Mehmet Emin Yurdakul', 'Ali Canip Yöntem', 'Fuat Köprülü'], 'Ziya Gökalp, Türkçülüğün Esasları adlı fikrî eserinin yanı sıra Kızıl Elma, Yeni Hayat ve Altın Işık ile Millî Edebiyat\'ın düşünsel-poetik çerçevesini çizmiştir.'),
  ('Servetifünun şiirinde sıkça kullanılan "sone, terzarima, triyole" ve geliştirilen "serbest müstezat" biçimleri bu dönemin hangi eğilimini gösterir?', 'Klasik nazım biçimlerini kırarak Batılı ve esnek biçim arayışlarına yöneldiğini', ['Halk şiirindeki koşma ve semai biçimlerine tam bir bağlılık gösterdiğini', 'Şiirde biçim kaygısını tamamen bırakıp düz yazı cümlelerine geçtiğini', 'Divan şiirindeki kaside ve terkibibent kurallarını aynen koruduğunu'], 'Servetifünun şairleri Fransız şiirinden sone ve terzarimayı almış, Divan müstezatını da esneterek serbest müstezata dönüştürmüşlerdir.'),
  ('Âşık tarzı Halk edebiyatında sekizli hece ölçüsü ve kendine özgü kıvrak ezgisiyle sevgi, doğa ve güzellik konularını işleyen nazım biçimi aşağıdakilerden hangisidir?', 'Semai', ['Varsağı', 'Destan', 'İlahi'], 'Sekizli hece ölçüsüyle ve özel bir ezgiyle söylenen, çoğunlukla Karacaoğlan ile özdeşleşen lirik halk şiiri nazım biçimi semaidir.'),
  ('"Bre ağalar bre beyler / Ölmeden bir dem sürelim" ünlemleriyle başlayan ve yiğitçe, mertçe bir eda taşıyan sekizli hece ölçülü Halk şiiri biçimi hangisidir?', 'Varsağı', ['Koşma', 'Türkü', 'Devriye'], 'Güney Anadolu\'daki Varsak Türkmenlerinin ürettiği, sekizli heceyle ve "bre, hey, behey" gibi ünlemlerle yiğitçe söylenen biçim varsağıdır.'),
  ('Tanzimat I. Dönem\'de Ahmet Mithat Efendi\'nin yazdığı "Felatun Bey ile Rakım Efendi" romanında yazarın okura örnek gösterdiği çalışkan, tutumlu ve kendi değerlerine bağlı kahraman kimdir?', 'Rakım Efendi', ['Felatun Bey', 'Bihruz Bey', 'Ali Bey'], 'Ahmet Mithat; mirasyedi ve yüzeysel Batı taklitçisi Felatun Bey\'in karşısına çalışkan, hem Doğu hem Batı kültürünü özümsemiş ideal tip olarak Rakım Efendi\'yi çıkarır.'),
  ('Cumhuriyet Dönemi\'nde "Bayrak şairi" olarak tanınan Arif Nihat Asya ile "Bu Vatan Kimin?" şiirinin yazarı Orhan Şaik Gökyay\'ı birleştiren ortak şiir çizgisi hangisidir?', 'Millî Edebiyat zevk ve anlayışını sürdüren epik-lirik memleket ve tarih şiiri', ['İkinci Yeni akımının soyut ve gerçeküstücü imge anlayışına dayalı kapalı şiir', 'Garip hareketinin kahramanlık ve şairaneliği alaya alan ironik sokak şiiri', 'Servetifünun geleneğinin bireysel melankoli ve kaçış temalı salon şiiri'], 'Arif Nihat Asya ve Orhan Şaik Gökyay; tarih bilinci, vatan sevgisi ve kahramanlık temalarını yaşayan Türkçeyle işleyerek Millî Edebiyat çizgisini sürdürmüşlerdir.'),
  ('Divan şiirine Türk şairlerinin kazandırdığı ve özellikle Lale Devri\'nde Nedim\'le zirveye ulaşan, bestelenmek üzere dörtlüklerle yazılan nazım biçimi hangisidir?', 'Şarkı', ['Rubai', 'Murabba', 'Kıta'], 'Halk edebiyatındaki türkünün karşılığı olarak Divan şiirine Türklerin kazandırdığı, nakaratlı ve bestelenmeye uygun dörtlük biçimi şarkıdır.'),
  ('Servetifünun Dönemi\'nde "mensur şiir" türünün ilk ve en yetkin örneklerini ("Mensur Şiirler", "Mezardan Sesler") veren yazar aşağıdakilerden hangisidir?', 'Halit Ziya Uşaklıgil', ['Hüseyin Cahit Yalçın', 'Ahmet Hikmet Müftüoğlu', 'Süleyman Nazif'], 'Batı edebiyatından alınan ve şairane duyuşu ölçü-uyak olmadan düzyazı cümleleriyle sunan mensur şiirin bizdeki kurucusu Halit Ziya Uşaklıgil\'dir.'),
  ('Halk edebiyatında âşıkların saz eşliğinde belli bir kurala bağlı kalarak birbirlerini mat etmek amacıyla yaptıkları karşılıklı şiir söyleme geleneğine ne ad verilir?', 'Atışma', ['Lebdeğmez', 'Muamma', 'Koçaklama'], 'Âşık fasıllarında iki veya daha fazla âşığın ayak (uyak) vererek birbirini söz ustalığı ve bilgiyle sınadığı karşılıklı söyleşmeye atışma denir.'),
  ('"Korkma, sönmez bu şafaklarda yüzen al sancak" dizesiyle başlayan İstiklal Marşı\'nın şairi Mehmet Akif Ersoy\'un tüm şiirlerini topladığı yedi kitaplık eserin adı nedir?', 'Safahat', ['Tamâm-ı Kelâm', 'Kendi Gök Kubbemiz', 'Çile'], 'Mehmet Akif Ersoy, Türk milletine armağan ettiği İstiklal Marşı dışındaki manzumelerini yedi kitaptan oluşan "Safahat" adlı külliyatında toplamıştır.'),
  ('Tanzimat II. Dönem\'de Muallim Naci\'nin eski edebiyat taraftarlarının sözcüsü konumuna gelmesine karşın Batılı tarzda sade ve başarılı şiirler topladığı ünlü kitabının adı nedir?', 'Ateşpare', ['Zemzeme', 'Validem', 'Nağme-i Seher'], 'Eski-yeni tartışmasında geleneği savunan Muallim Naci; Ateşpare, Şerare ve Füruzan gibi eserlerinde Batılı biçim ve sade Türkçeyle ("Köylü Kızların Şarkısı") yenilikçi örnekler de vermiştir.'),
  ('Cumhuriyet Dönemi\'nde "Destan şairi" olarak anılan ve "Üç Şehitler Destanı", "Çakır\'ın Destanı" gibi eserleriyle tanınan şair aşağıdakilerden hangisidir?', 'Fazıl Hüsnü Dağlarca', ['Cahit Külebi', 'Bedri Rahmi Eyüboğlu', 'Ahmet Muhip Dıranas'], '"Türkçem, benim ses bayrağım" diyen Fazıl Hüsnü Dağlarca; Kurtuluş Savaşı ve Çanakkale üzerine yazdığı büyük yapma destanlarının yanı sıra metafizik ve çocuk şiirleriyle tanınır.'),
  ('Millî Edebiyat Dönemi\'nde "Çalıkuşu" romanıyla Anadolu\'ya yönelişin en sevilen örneklerinden birini veren ve Cumhuriyet Dönemi\'nde de eser üretmeyi sürdüren yazar kimdir?', 'Reşat Nuri Güntekin', ['Refik Halit Karay', 'Aka Gündüz', 'Ömer Seyfettin'], 'Reşat Nuri Güntekin, İstanbullu genç öğretmen Feride\'nin Anadolu kasaba ve köylerindeki serüvenini anlattığı Çalıkuşu ile Anadolu romantizmi ve gözlemciliğini birleştirmiştir.'),
  ('Tanzimat I. Dönem\'de Namık Kemal\'in tiyatroyu "eğlencelerin en faydalısı" olarak tanımlaması onun hangi sanat anlayışına bağlı olduğunu gösterir?', 'Sanatı halkı eğitmek ve toplumu bilinçlendirmek için bir araç gören "toplum için sanat" anlayışına', ['Sanat eserinin hiçbir ahlaki veya sosyal amaç taşımaması gerektiğini savunan saf sanat anlayışına', 'Tiyatronun yalnızca saray çevresindeki seçkinleri güldürmek için yazılması gerektiği görüşüne', 'Sahne eserlerinde konuşma dili yerine ağır ve kapalı sembollerin kullanılması ilkesine'], 'Namık Kemal romantizm akımının ve Tanzimat idealizminin etkisiyle tiyatroyu okuma yazma bilmeyen geniş halk kitlelerini aydınlatacak bir okul saymıştır.'),
  ('Cumhuriyet Dönemi\'nde "Fahriye Abla", "Olvido" ve "Kar" gibi şiirleriyle hece ölçüsünü duru, modern ve masalsı bir ahenkle kullanan saf şiir şairi kimdir?', 'Ahmet Muhip Dıranas', ['Enis Behiç Koryürek', 'İlhan Berk', 'Ece Ayhan'], 'Ahmet Muhip Dıranas, Fransız sembolizmi özellikle Baudelaire etkisiyle hece ölçüsünün kalıplarını genişletip Türkçede saf şiirin en seçkin örneklerini vermiştir.'),
  ('Anonim Halk edebiyatında ölen bir kişinin gençliğini, iyiliklerini ve ölümünden duyulan acıyı ezgiyle anlatan şiirlere "ağıt" denir. Bu türün İslamiyet öncesi ve Divan edebiyatındaki karşılıkları sırasıyla hangisidir?', 'Sagu - Mersiye', ['Koşuk - Gazel', 'Sav - Hikmet', 'Destan - Kaside'], 'Ölüm ve yas konulu şiirlere İslamiyet öncesi sözlü dönemde sagu, Halk edebiyatında ağıt, Divan edebiyatında ise mersiye (örneğin Baki\'nin Kanuni Mersiyesi) denir.'),
  ('Cumhuriyet Dönemi\'nde "Yedi Meşaleciler" topluluğunun şiir alanında en sadık temsilcisi kalan ve "Sebil ve Güvercinler", "Geçen Zaman", "Nefes Almak" adlı eserleriyle tanınan şair kimdir?', 'Ziya Osman Saba', ['Cevdet Kudret Solok', 'Kenan Hulusi Koray', 'Muammer Lütfi Bahşi'], 'Yedi Meşaleciler dağıldıktan sonra diğer üyeler roman ve araştırmaya yönelirken Ziya Osman Saba ev, aile, çocukluk özlemi ve tevekkül temalı saf şiiri sürdürmüştür.'),
  ('"Dinle sana bir nasihat edeyim / Hatırdan, gönülden geçici olma / Yiğidin başına bir iş gelirse / Anı yâd ellere açıcı olma" Karacaoğlan\'a (veya âşık geleneğine) ait bu dörtlük içerik bakımından hangi özelliği taşır?', 'Didaktik (öğretici) ve ahlaki öğüt verici halk bilgeliğini', ['Doğadaki bahar uyanışını anlatan pastoral betimlemeyi', 'Savaş meydanındaki kahramanlığı öven epik coşkuyu', 'Toplumdaki yöneticileri sertçe eleştiren satirik yergiyi'], 'İlk dizedeki "nasihat edeyim" ifadesi ve sonraki dizelerdeki insani-ahlaki öğütler, parçanın didaktik nitelikli bir âşık deyişi olduğunu açıkça gösterir.'),
  ('Servetifünun Dönemi\'nde "kavga ve eleştiri" yazılarıyla topluluğu dış saldırılara karşı savunan, "Edebiyat ve Hukuk" makalesinin çevirisi yüzünden derginin kapatılmasına yol açan yazar kimdir?', 'Hüseyin Cahit Yalçın', ['Mehmet Rauf', 'Cenap Şahabettin', 'Ahmet Şuayp'], '"Nadide" ve "Hayal İçinde" romanlarının da yazarı olan Hüseyin Cahit Yalçın, "Kavgalarım"da topladığı polemikleri ve "Edebiyat ve Hukuk" çevirisiyle tanınır.'),
  ('Divan edebiyatında bir şairin başka bir şairin gazelini aynı ölçü ve uyakla, ancak alay etmek ve şaka yapmak amacıyla yeniden yazmasına ne ad verilir?', 'Tehzil', ['Nazire', 'Tahmis', 'Taştir'], 'Beğenilen bir şiire aynı ölçü ve uyakla ciddi benzerini yazmaya nazire, şaka ve alay (parodi) amacıyla benzerini yazmaya ise tehzil (hezel) denir.'),
  ('Millî Edebiyat Dönemi\'nde "Vurun Kahpeye", "Ateşten Gömlek" ve "Sinekli Bakkal" gibi romanlarıyla hem Kurtuluş Savaşı\'nı hem de toplumsal-kültürel sentezi işleyen yazar kimdir?', 'Halide Edip Adıvar', ['Müfide Ferit Tek', 'Şükûfe Nihal Başar', 'Halide Nusret Zorlutuna'], 'Halide Edip; ilk dönem psikolojik romanlarından (Handan) sonra Ateşten Gömlek\'le Milli Mücadele\'yi, Sinekli Bakkal\'la Doğu-Batı sentezini ve töre romanını yazmıştır.'),
  ('Halk edebiyatında "Dede Korkut Hikâyeleri"nin edebiyat tarihimizdeki geçiş rolünü en doğru açıklayan yargı aşağıdakilerden hangisidir?', 'Destan geleneğinden halk hikâyeciliğine ve İslamiyet öncesi kültürden İslami döneme geçişin başyapıtı olması', ['Divan edebiyatındaki mesnevi türünden Batılı anlamdaki psikolojik romana geçişi sağlaması', 'Tanzimat tiyatrosundan Cumhuriyet Dönemi epik tiyatrosuna geçişin ilk yazılı metni olması', 'Aruz ölçüsüyle yazılmış ilk Türkçe siyasetname ve öğüt kitabı niteliği taşıması'], 'Nazım-nesir karışık on iki (nüshalarla on üç) boydan oluşan Dede Korkut Kitabı, Oğuzların destan çağından halk hikâyesine ve İslami kimliğe geçişini yansıtır.'),
  ('İslamiyet etkisindeki Türk edebiyatının bilinen ilk büyük eseri olan ve Yusuf Has Hacip tarafından mesnevi biçimiyle yazılıp Tabgaç Buğra Han\'a sunulan alegorik eser hangisidir?', 'Kutadgu Bilig', ['Divânu Lugâti\'t-Türk', 'Atabetü\'l-Hakâyık', 'Divân-ı Hikmet'], '1069-1070\'te yazılan Kutadgu Bilig ("Mutluluk Veren Bilgi"); adalet, devlet, akıl ve akıbeti dört sembolik kişiyle anlatan ilk İslami Türk mesnevisi ve siyasetnamesidir.'),
  ('Divan şiirinde sevgilinin kaşının "kemana (yaya)", kirpiklerinin "oka", bakışının "hançere" benzetilmesi aşağıdakilerden hangisiyle adlandırılır?', 'Mazmun', ['Tapşırma', 'Seci', 'Redif'], 'Divan edebiyatında belirli kavramları ve güzellik unsurlarını karşılamak üzere şairlerin ortaklaşa kullandığı kalıplaşmış simge ve benzetmelere mazmun denir.'),
  ('Cumhuriyet Dönemi\'nde "Memleketimden İnsan Manzaraları" ve "Kuvâyi Milliye" adlı büyük destansı eserleri serbest nazım ve sinema-roman tekniklerinden yararlanarak yazan şair kimdir?', 'Nazım Hikmet Ran', ['Rıfat Ilgaz', 'Hasan İzzettin Dinamo', 'A. Kadir'], 'Nazım Hikmet, "Memleketimden İnsan Manzaraları"nda şiir, roman, senaryo ve tarih öğelerini birleştirerek 20. yüzyıl Türkiye\'sinin dev bir panoramasını çizmiştir.'),
  ('Servetifünun şiirinde kulak için uyak anlayışının yanı sıra dize ortalarında "ah, ey, of" gibi ünlemlere çok sık yer verilmesi dönemin hangi ruhsal özelliğini yansıtır?', 'Aşırı duygusallık, melankoli ve içli-kırılgan sanatçı duyarlılığını', ['Savaş meydanlarındaki yiğitlik ve zafer coşkusunu', 'Halk edebiyatındaki varsağı geleneğine duyulan hayranlığı', 'Toplumsal sorunlar karşısındaki alaycı ve mizahi kayıtsızlığı'], 'Servetifünun şairleri (özellikle Celal Sahir, Hüseyin Siret, Tevfik Fikret\'in ilk dönemi) marazi duyarlılık ve melankoliyi kırık dizeler ve iç çekiş ünlemleriyle dışa vurmuştur.'),
  ('Cumhuriyet Dönemi\'nde "Yalnızız", "Matmazel Noraliya\'nın Koltuğu" ve "Bir Tereddüdün Romanı" adlı eserlerinde madde-ruh ikilemini ve mistik yönelişi işleyen yazar kimdir?', 'Peyami Safa', ['Abdülhak Şinasi Hisar', 'Samiha Ayverdi', 'Reşat Nuri Güntekin'], 'Psikolojik romanın büyük ustası Peyami Safa; özellikle Matmazel Noraliya\'nın Koltuğu ve Yalnızız\'da pozitivizm-materyalizm eleştirisi ve ruhçuluk (mistisizm) çizgisini derinleştirmiştir.'),
  ('"Ete kemiğe büründüm / Yunus diye göründüm" dizelerinde iki dizeyle koca bir varoluş ve yaratılış felsefesini en sade sözcüklerle anlatma sanatına ne ad verilir?', 'Sehl-i mümteni', ['Hüsnütalil', 'Tecahülüarif', 'Mübalağa'], 'İlk bakışta çok kolay ve sade görünen, ancak derin bir anlam taşıdığı için benzerini söylemek çok güç olan özlü anlatıma sehl-i mümteni denir.'),
  ('Kadeş Antlaşması\'nda Hitit kralı III. Hattuşili ile birlikte kraliçe Puduhepa\'nın da mührünün bulunması, Hitit yönetim anlayışı hakkında hangi çıkarımı doğrular?', 'Kraliçenin devlet yönetiminde ve diplomatik kararlarda resmi yetkiye sahip olduğunu', ['Hititlerde hükümdarlığın babadan oğula değil doğrudan anaerkil soy üzerinden geçtiğini', 'Antlaşma metinlerinin yalnızca tapınak rahibeleri tarafından kaleme alınabildiğini', 'Mısır firavunlarının Hitit iç işlerine müdahale ederek kraliçeyi naip atadığını'], 'Hititlerde Tavananna unvanlı kraliçe, devlet işlerinde ve uluslararası antlaşmalarda kralla birlikte imza ve mühür yetkisine sahipti.'),
  ('Hammurabi Kanunları\'nın giriş kısmında kralın kendisini "Tanrı Şamaş\'tan adalet yasalarını alan koruyucu çoban" olarak tanımlaması neyi amaçlamaktadır?', 'Yasaların meşruiyetini ilahi bir kaynağa dayandırarak toplumsal itaati güçlendirmeyi', ['Babil ülkesinde çok tanrılı inancı kaldırıp tek tanrılı ruhban sınıfı kurmayı', 'Rahiplerin yargı yetkisini tamamen ellerinden alıp laik bir hukuk düzeni getirmeyi', 'Yazılı hukuk kurallarını yalnızca tapınak görevlilerinin yargılanmasında uygulamayı'], 'Hammurabi, kanunları güneş ve adalet tanrısı Şamaş\'tan alır şekilde betimlenerek kurallara karşı çıkılmasını dini açıdan da engellemek istemiştir.'),
  ('Çin yıllıkları Şi-Ci\'de Asya Hun hükümdarı Mete Han\'ın komşu Tunguzların çorak bir sınır toprağını istemesi üzerine "Toprak milletin köküdür, onu nasıl verebilirim?" diyerek sefer başlatması neyi gösterir?', 'Ülke toprağının hükümdarın şahsi malı değil, devletin ve milletin varlık temeli sayıldığını', ['Hunların yerleşik tarım toplumuna geçerek sınır kaleleri inşa etmeye başladığını', 'Bozkır devletlerinde diplomatik sorunların her zaman toprak taviziyle çözüldüğünü', 'Çorak arazilerin maden rezervleri bakımından verimli ovalardan daha değerli görüldüğünü'], 'Mete Han\'ın sözü, Türk devlet geleneğinde vatan toprağının kişisel mülk gibi devredilemeyeceği anlayışını yansıtır.'),
  ('Hz. Muhammed\'in Medine Sözleşmesi\'nde "Yahudilerin dinleri kendilerine, Müslümanların dinleri kendilerinedir; şehre saldırı olursa taraflar birlikte savunma yapacaktır" hükmüne yer vermesi neyi sağlamıştır?', 'Farklı inanç gruplarını ortak vatandaşlık ve güvenlik paydasında birleştiren toplumsal bir sözleşme kurmayı', ['Medine\'deki tüm kabilelerin İslam dinini kabul ederek tek bir mezhep çatısı altında toplanmasını', 'Mekke ile süren kervan ticaretinin vergi gelirlerini yalnızca Yahudi kabileler arasında paylaştırmayı', 'Şehir yönetimini kabile şeyhlerinden oluşan kalıtsal bir senatoya devretmeyi'], 'Medine Vesikası, inanç özgürlüğünü güvenceye alırken ortak vatan savunması yükümlülüğü getirmiştir.'),
  ('Yusuf Has Hacib\'in Kutadgu Bilig adlı eserinde "Bey halka kanun ile hükmetmeli; gümüş ve altını adaletle dağıtmalıdır" öğüdünü vermesi hangi devlet anlayışını yansıtır?', 'Siyasi iktidarın devamlılığını hukukun üstünlüğüne ve sosyal adalete bağlayan anlayışı', ['Hükümdarın mutlak iradesinin her türlü töre ve kanunun üzerinde sayıldığı anlayışı', 'Devlet hazinesinin yalnızca hanedan üyeleri arasında paylaştırılması gerektiği ilkesini', 'Ekonomik refahın sadece dış fetihlerden elde edilecek ganimetlere dayandırılmasını'], 'Kutadgu Bilig\'de adalet (Könilik), devletin ayakta kalmasının ve halkın mutluluğunun temel şartı olarak sunulur.'),
  ('Anadolu Selçuklu Sultanı I. Alaeddin Keykubad\'ın Venedik ve Kıbrıs krallıklarıyla yaptığı ticaret antlaşmalarında "korsan veya eşkıya saldırısına uğrayan tüccarın zararının hazineden ödeneceğini" taahhüt etmesi neyi hedefler?', 'Devlet sigortası uygulamasıyla uluslararası ticaret yollarını Anadolu limanlarına çekmeyi', ['Yabancı tüccarlara sınırsız adli dokunulmazlık vererek yerli loncaları tasfiye etmeyi', 'Akdeniz\'deki tüm ticaret gemilerini Selçuklu donanmasına vergi ödemeden bağlamayı', 'Kervansarayların işletmesini Venedikli banker ailelere devrederek gelir sağlamayı'], 'Selçuklular, zarar tazmini (devlet sigortası) ve düşük gümrük vergileriyle Anadolu\'yu güvenli bir transit ticaret merkezi haline getirmiştir.'),
  ('Orhan Gazi\'nin 1324 tarihli Mekece Vakfiyesi\'nde vakıf yöneticisi olarak azatlı kölesi Şerefeddin Mukbil\'i ataması, erken dönem Osmanlı idaresi hakkında neyi gösterir?', 'Liyakat sahibi kul kökenli kişilerin idari ve mali görevlerde değerlendirilmeye başlandığını', ['Hanedan üyelerinin vakıf kurma ve yönetme hakkından tamamen mahrum bırakıldığını', 'Bursa ve çevresindeki tüm tarım topraklarının kölelere mülk olarak dağıtıldığını', 'Osmanlı Beyliği\'nde resmi belgelerin yalnızca Farsça yerine Rumca düzenlendiğini'], 'Mekece Vakfiyesi, Osmanlı\'ya ait bilinen en eski resmi vakıf belgesidir ve kul kökenli görevlilerin güvenceli biçimde yönetime katıldığını belgeler.'),
  ('1533 İstanbul Antlaşması\'nın "Avusturya Arşidükü protokol bakımından Osmanlı Sadrazamı\'na denk sayılacaktır" maddesi neyi ifade eder?', 'Osmanlı Padişahı\'nın Orta Avrupa\'da siyasi ve diplomatik üstünlüğünü Avusturya\'ya kabul ettirdiğini', ['Avusturya Arşidükü\'nün Kutsal Roma Germen İmparatoru unvanından resmen feragat ettiğini', 'Sadrazamın padişahtan bağımsız olarak yabancı devletlerle antlaşma imzalama yetkisi aldığını', 'İki devlet arasında tam eşitlik ilkesine dayalı modern diplomasi kurallarının uygulandığını'], 'Avusturya hükümdarının Osmanlı\'nın ikinci adamı olan sadrazama eşit sayılması, Osmanlı Padişahı\'nın protokol üstünlüğünü simgeler.'),
  ('Evliya Çelebi\'nin Seyahatname\'sinde İstanbul esnaf alaylarını anlatırken "Ehl-i hiref loncalarında çıraklıktan kalfalığa ve ustalığa geçişin şed kuşatma töreni ve kalite denetimiyle yapıldığını" belirtmesi neyi gösterir?', 'Mesleki eğitimin, üretim standartlarının ve iş ahlakının lonca teşkilatınca sıkı kurallara bağlandığını', ['Osmanlı şehirlerinde serbest piyasa rekabetinin hiçbir denetime tabi olmadan işlediğini', 'Zanaat kollarında yalnızca gayrimüslim ustaların dükkan açma (gedik) hakkına sahip olduğunu', 'Sanayi Devrimi tarzı seri fabrika üretiminin İstanbul\'da erken dönemde başladığını'], 'Lonca sistemi; mesleki yeterliliği, mal kalitesini ve fiyat (narh) dengesini denetleyerek üretici ile tüketiciyi korumuştur.'),
  ('III. Ahmed\'in İbrahim Müteferrika ve Said Efendi\'ye verdiği 1727 tarihli matbaa fermanında "fıkıh, tefsir, hadis ve kelam kitapları dışındaki tarih, tıp, coğrafya ve sözlük eserlerinin basılmasına izin verilmesi" neyle açıklanır?', 'Dini hassasiyetleri ve binlerce hattatın geçim kaygısını gözeterek yeniliğe tepki doğmasını önlemekle', ['Osmanlı medreselerinde dini ilimlerin okutulmasının o tarihten itibaren yasaklanmasıyla', 'Avrupa\'dan getirilen matbaa harflerinin Arap alfabesiyle dini metin basmaya teknik olarak elverişsiz olmasıyla', 'Şeyhülislamlık makamının tarih ve coğrafya kitaplarının okunmasını zorunlu kılmasıyla'], 'Matbaa fermanındaki sınırlama hem kutsal metinlerin saygınlığını koruma hem de el yazmasıyla geçinen hattat esnafının ekonomik tepkisini azaltma amacı taşır.'),
  ('II. Mahmud\'un 1826\'da Yeniçeri Ocağı\'nı kaldıran fermanının vak\'anüvis Esad Efendi tarafından "Üss-i Zafer" adlı eserde "Vaka-i Hayriye" (Hayırlı Olay) olarak nitelendirilmesinin temel nedeni nedir?', 'Yeniliklerin önündeki en büyük silahlı muhalefet odağının tasfiye edilerek merkezi otoritenin ve reform sürecinin önünün açılması', ['Osmanlı Devleti\'nin Yunan isyanını tek başına bastırarak Mora Yarımadası\'nda kesin hakimiyet kurması', 'Tımar sisteminin yeniden canlandırılarak kapıkulu maaşlarının tamamen ortadan kaldırılması', 'Avrupa devletlerinin Osmanlı\'dan istediği tüm savaş tazminatlarının bağışlanması'], 'Yeniçeri Ocağı\'nın kaldırılması, padişahın mutlak otoritesini yeniden kurmasını ve idari-askeri modernleşme hamlelerini başlatmasını sağlamıştır.'),
  ('1839 Tanzimat Fermanı\'nda padişahın "Hiçbir kimsenin yargılanmadan cezalandırılmayacağını, müsadere usulünün kaldırıldığını ve kendisinin de çıkarılacak kanunlara uyacağına yemin ettiğini" ilan etmesi neyin kanıtıdır?', 'Kanun gücünün üstünlüğünün padişah iradesiyle kabul edildiğinin ve özel mülkiyet güvencesinin sağlandığının', ['Saltanat makamının kaldırılarak egemenliğin kayıtsız şartsız millete devredildiğinin', 'Gayrimüslim tebaanın devlet memurluğuna ve askerlik hizmetine alınmasının yasaklandığının', 'Şer\'i mahkemelerin tümüyle kapatılarak İsviçre Medeni Kanunu\'nun yürürlüğe konulduğunun'], 'Gülhane Hatt-ı Hümayunu ile ilk kez padişah kendi gücünün üstünde kanun gücünü tanımış ve müsadereyi kaldırarak mülkiyet hakkını güvenceye almıştır.'),
  ('1881 tarihli Muharrem Kararnamesi uyarınca kurulan Düyun-ı Umumiye İdaresi\'ne "tuz, tütün, damga, içki, balık avı ve ipek öşrü gelirlerinin doğrudan tahsil edilip alacaklı Avrupalı tahvil sahiplerine ödenmesi" yetkisinin verilmesi neyin göstergesidir?', 'Osmanlı Devleti\'nin mali bağımsızlığını büyük ölçüde kaybederek temel gelir kaynaklarının yabancı denetimine girdiğinin', ['Osmanlı bütçesinin ilk kez gelir fazlası vererek tüm dış borçlarını tek seferde kapattığının', 'Yabancı sermayeli bankaların kamulaştırılarak Milli İktisat politikasına geçildiğinin', 'Kapitülasyonların tek taraflı olarak feshedilip gümrük duvarlarının yükseltildiğinin'], 'Muharrem Kararnamesi ile kurulan Genel Borçlar İdaresi, devlet içinde devlet gibi çalışarak Osmanlı\'nın vergi toplama egemenliğini zedelemiştir.'),
  ('Osmanlı Hükümeti\'nin I. Dünya Savaşı\'na girerken 1914 sonbaharında yayımladığı iradeyle "her türlü mali, iktisadi ve adli kapitülasyonların tek taraflı olarak kaldırıldığını" ilan etmesine Almanya ve Avusturya-Macaristan\'ın dahi nota vererek itiraz etmesi neyi kanıtlar?', 'Avrupalı devletlerin kendi blok çıkarları söz konusu olduğunda müttefiklerinin bile ekonomik ayrıcalıklarından vazgeçmek istemediğini', ['Osmanlı Devleti\'nin İtilaf Devletleri safında savaşa girmek için gizli görüşmeler yürüttüğünü', 'Kapitülasyonların kaldırılmasının yalnızca tarafsız Balkan ülkelerini ekonomik zarara uğrattığını', 'Almanya\'nın Bağdat Demiryolu imtiyazını karşılıksız olarak Osmanlı hazinesine devrettiğini'], 'Müttefikleri Almanya ve Avusturya\'nın bile kapitülasyonların kaldırılmasına karşı çıkması, devletler arası ilişkilerde ekonomik çıkarların belirleyiciliğini gösterir.'),
  ('Lidya Kralı Kroisos dönemine ait elektron ve altın sikkelerin üzerinde krallık arması olan aslan ve boğa kabartmalarının bulunması neyi güvence altına almıştır?', 'Madenin ağırlık ve saflık ayarının siyasi otorite tarafından garanti edilerek ticaretin hızlanmasını', ['Takas ekonomisinin kanunen zorunlu kılınıp yabancı tüccarların ülkeye girişinin yasaklanmasını', 'Sikkelerin yalnızca tapınaklara sunulan dini adak eşyası olarak kullanılmasını', 'Kral Yolu üzerindeki tüm gümrük vergilerinin İyon şehir devletlerine bırakılmasını'], 'Üzerinde devlet mührü taşıyan sikkenin icadı, her alışverişte külçe maden tartma zorunluluğunu kaldırarak mübadeleyi kolaylaştırmıştır.'),
  ('532 yılında İstanbul\'da çıkan Nika İsyanı sonrasında İmparator I. Justinianus\'un yıkılan Ayasofya\'yı çok daha görkemli kubbeli bir mimariyle yeniden inşa ettirip açılışta "Ey Süleyman, seni geçtim!" demesi neyi simgeler?', 'Sarsılan imparatorluk otoritesini ve ilahi meşruiyet iddiasını anıtsal mimari yoluyla yeniden tüm dünyaya ilan etme arzusunu', ['Doğu Roma İmparatorluğu\'nun Kudüs\'teki Yahudi tapınağını başkent İstanbul\'a taşıma kararını', 'Ortodoks Kilisesi\'nin siyasi iktidarı imparatorun elinden alarak teokratik cumhuriyet kurmasını', 'Sasani İmparatorluğu ile yapılan Ebedi Barış Antlaşması\'nın geçersiz sayılmasını'], 'Justinianus, Nika Ayaklanması\'nı bastırdıktan sonra mutlak gücünü ve Hristiyan Roma\'nın ihtişamını Ayasofya\'nın mimarisiyle somutlaştırmıştır.'),
  ('Kaşgarlı Mahmud\'un 1072-1074 yıllarında yazdığı Divanü Lügati\'t-Türk adlı eserini Bağdat\'taki Abbasi Halifesi Muktedi-Billah\'a sunarken "Türk dilinin Arapça ile atbaşı yarışacak zenginlikte olduğunu" örneklerle göstermesi neyi amaçlar?', 'İslam dünyasında siyasi ve askeri liderliği üstlenen Türklerin dil ve kültür gücünü Arap aydınlarına kanıtlamayı', ['Abbasi Halifeliği\'ni ortadan kaldırarak Bağdat\'ta laik bir Türk hakanlığı kurmayı', 'Medreselerde Arapça eğitim yapılmasını yasaklayıp Uygur alfabesini zorunlu kılmayı', 'Türk boylarının İslamiyet öncesi tüm sözlü edebiyat ürünlerini unutturmayı'], 'Kaşgarlı Mahmud, Araplara Türkçeyi öğretmek ve Türk dilinin yüksek bir medeniyet dili olduğunu kanıtlamak amacıyla bu ansiklopedik sözlüğü hazırlamıştır.'),
  ('İbn Battuta\'nın 14. yüzyılda Anadolu\'yu gezerken kaleme aldığı seyahatnamesinde "Her kasabada Ahilerin bekar genç zanaatkarlardan oluşan zaviyelerinin bulunduğunu, gündüz kazandıklarıyla akşam yolcuları ağırladıklarını ve zalimleri engellediklerini" yazması neyi gösterir?', 'Ahilik teşkilatının yalnızca ekonomik üretimle sınırlı kalmayıp toplumsal dayanışma ve iç güvenliğe de katkı sunduğunu', ['Anadolu\'da şehir yönetiminin tamamen Bizanslı valilerin kontrolünde olduğunu', 'Ahi zaviyelerinin devlet hazinesinden aldığı vergilerle askeri kışla olarak çalıştığını', 'Yabancı gezginlerin Anadolu şehirlerinde konaklamasının sıkı yasaklara tabi tutulduğunu'], 'İbn Battuta\'nın tanıklığı, siyasi otoritenin zayıfladığı beylikler döneminde Ahilerin sosyal yardımlaşma, ahlak ve asayiş işlevi gördüğünü kanıtlar.'),
  ('Yavuz Sultan Selim\'in 1514 Çaldıran Seferi öncesinde Anadolu\'da Safevi propagandası yapan Şahkulu benzeri gruplara karşı aldığı tedbirlere ilişkin mühimme kayıtları ve İdris-i Bitlisi\'nin kroniği neyi ortaya koyar?', 'Osmanlı-Safevi çatışmasının yalnızca sınır anlaşmazlığı olmayıp Anadolu üzerindeki siyasi ve mezhepsel nüfuz mücadelesinden kaynaklandığını', ['Safevilerin Venedik donanmasıyla birleşerek İstanbul Boğazı\'nı denizden kuşattığını', 'Doğu Anadolu\'daki tüm Kürt beylerinin Çaldıran Savaşı\'nda Şah İsmail safında yer aldığını', 'İpek Yolu\'nun Tebriz güzergahının ticari değerini tümüyle kaybettiğini'], 'Şah İsmail\'in Anadolu\'daki Türkmenler üzerinde yürüttüğü propaganda Osmanlı iç düzenini tehdit etmiş, İdris-i Bitlisi\'nin diplomatik çabasıyla Doğu Anadolu beyleri Osmanlı\'ya bağlanmıştır.'),
  ('Katip Çelebi\'nin 1656\'da yazdığı "Düsturu\'l-Amel li-Islahi\'l-Halel" adlı risalesinde devleti insan bedenine benzeterek "hazineyi mideye, askeri balgama, reayayı sevdaya" eşleştirip bütçe açığını gidermek için saray ve asker masraflarının kısılmasını önermesi neyi gösterir?', 'On yedinci yüzyıl ıslahat düşünürlerinin mali ve idari bozulmanın iç nedenlerini teşhis etmeye başladığını', ['Katip Çelebi\'nin Avrupa üniversitelerinde tıp eğitimi alarak Batılı anayasa taslağı hazırladığını', 'Köprülü ailesi öncesinde Osmanlı bütçesinin hiçbir zaman açık vermediğini', 'Islahat raporlarında sorunun tek çözümü olarak yeni fetih seferlerine çıkılmasının gösterildiğini'], 'Katip Çelebi ve Tarhuncu Ahmed Paşa gibi isimler, sorunun kökeninde gelir-gider dengesizliğinin yattığını bilimsel benzetmelerle ortaya koymuştur.'),
  ('II. Mahmud döneminde çıkarılan 1831 tarihli Takvim-i Vekayi gazetesinin mukaddimesinde (önsözünde) "Devlet işlerinin iç yüzünü halkın doğru öğrenmesi ve asılsız söylentilerin önüne geçilmesi" amacının vurgulanması neyi gösterir?', 'Merkezi yönetimin yaptığı reformları halka anlatmak ve kamuoyunu yönlendirmek için ilk resmi basını devreye soktuğunu', ['Özel girişimcilerin hükümet politikalarını eleştirmesi için tam basın özgürlüğü tanındığını', 'Ülkede okuryazarlık oranının yüzde doksan seviyesine ulaştığının belgelendiğini', 'Yalnızca Fransızca basılan gazetenin yabancı elçilikleri bilgilendirmekle sınırlı tutulduğunu'], 'İlk resmi gazete olan Takvim-i Vekayi, II. Mahmud\'un merkezileşme ve ıslahat kararlarını tebaaya ve memurlara doğru biçimde duyurma aracıyken kamuoyu kavramının gelişmesini de başlatmıştır.'),
  ('II. Abdülhamid dönemi Maarif Salnamelerinde (eğitim yıllıklarında) taşra vilayetlerinde çok sayıda Rüştiye ve İdadi ile Sanayi-i Nefise, Hendese-i Mülkiye ve Ziraat mekteplerinin açıldığının görülmesi, buna karşın siyasi gazetelere sıkı sansür uygulanması nasıl özetlenebilir?', 'Siyasal muhalefet ve basın baskı altında tutulurken mesleki-modern eğitim ve bürokratik altyapı yatırımlarının hızla sürdürüldüğü', ['Yabancı ve azınlık okullarının tümünün kapatılarak ülkede eğitim birliğinin sağlandığı', 'Üniversite ve yüksekokullarda pozitif bilim derslerinin müfredattan çıkarıldığı', 'Meclis-i Mebusan\'ın kesintisiz çalıştırılarak eğitim bütçesinin milletvekillerince denetlendiği'], 'II. Abdülhamid yönetimi anayasayı askıya alıp basını denetlerken öte yandan imparatorluk çapında okullaşma, demiryolu ve telgraf ağını büyütmüştür.'),
  ('19 Mayıs 1919 sonrasında Mustafa Kemal Paşa\'nın yayımladığı Havza Genelgesi\'nde "İşgallere karşı protesto mitingleri düzenlenmesi, İtilaf Devletleri temsilcilerine ve İstanbul Hükümeti\'ne uyarı telgrafları çekilmesi, ancak bu gösterilerde Hristiyan ahaliye kesinlikle kötü davranılmaması" uyarısı neyi hedefler?', 'Milli bilinci uyandırırken Mondros\'un 7. ve 24. maddelerinin işletilmesine bahane verilmemesini', ['Anadolu\'daki gayrimüslim azınlıkların Kuva-yı Milliye birliklerine zorunlu asker yapılmasını', 'İstanbul Hükümeti\'nin onayı olmadan hiçbir şehirde cemiyet kurulmamasını', 'İzmir\'in Yunanlılar tarafından işgalinin yalnızca diplomatik notalarla kabullenilmesini'], 'Mustafa Kemal Paşa hem halkı işgallere karşı harekete geçirmek hem de azınlıklara saldırı bahanesiyle yeni işgaller yapılmasını önlemek istemiştir.'),
  ('Erzurum Kongresi kararlarında "Milli sınırlar içinde vatan bir bütündür, parçalanamaz; Kuva-yı Milliye\'yi etkin, milli iradeyi hakim kılmak esastır; manda ve himaye kabul olunamaz" ifadelerinin bulunması bu kongrenin hangi özelliğini gösterir?', 'Toplanış amacı bölgesel olmasına karşın aldığı kararlar bakımından tüm ulusu kapsayan genel bir nitelik taşıdığını', ['Yalnızca Doğu Anadolu ve Karadeniz vilayetlerinin kurtuluşuyla sınırlı yerel tedbirler aldığını', 'İstanbul Hükümeti ile ortak kabine kurarak padişah adına vergi toplamayı amaçladığını', 'Büyük devletlerden birinin teknik ve siyasi koruyuculuğunu geçici olarak benimsediğini'], 'Erzurum Kongresi doğu illeri delegeleriyle toplanmışsa da "milli sınırlar" ve "manda reddi" gibi tüm vatanı ilgilendiren temel ilkeleri belirlemiştir.'),
  ('24 Nisan 1920\'de Mustafa Kemal Paşa\'nın TBMM\'ye sunduğu önergede "TBMM\'nin üstünde bir güç yoktur; geçici kaydıyla bir hükümet başkanı tanımak veya padişah vekili atamak doğru değildir" maddelerinin kabul edilmesi neyi amaçlar?', 'Meclisin geçici değil kalıcı olduğunu vurgulamayı ve İstanbul\'dan bağımsız ulusal egemenlik esasını yerleştirmeyi', ['Saltanat ve hilafet makamlarının aynı gün çıkarılan kanunla resmen kaldırıldığını duyurmayı', 'Güçler ayrılığı ilkesini benimseyerek hükümeti meclis dışından teknokratlarla kurmayı', 'Padişah Vahdettin\'i Ankara\'ya getirerek Meclis Başkanlığı görevine seçmeyi'], '"Geçici hükümet başkanı veya padişah kaymakamı atanamaz" ilkesi, TBMM\'nin iradesini saraya bağımlı kılacak her türlü girişimi engellemiştir.'),
  ('Mustafa Kemal Paşa\'nın Kütahya-Eskişehir Muharebeleri devam ederken 15 Temmuz 1921\'de Ankara\'da toplanan Maarif Kongresi\'nin açılış konuşmasında "Silahıyla olduğu kadar dimağıyla da mücadele etmek zorunda olan milletimizin cehaleti yenmesi şarttır; milli ve çağdaş bir eğitim programı hazırlanmalıdır" demesi neyi gösterir?', 'En bunalımlı savaş ortamında bile yeni devletin geleceğini çağdaş ve milli eğitim temeli üzerine kurma vizyonunu', ['Cephedeki öğretmenlerin tamamının ordudan terhis edilerek okullara geri gönderildiğini', 'Tevhid-i Tedrisat Kanunu ile yeni Türk harflerinin kongre günü yürürlüğe girdiğini', 'Yunan ordusunun Eskişehir önlerinden geri çekilerek ateşkes talep ettiğini'], 'Cephede ordunun Sakarya doğusuna çekildiği zor günlerde Maarif Kongresi\'nin toplanması, kültür ve eğitim bağımsızlığına verilen hayati önemi kanıtlar.'),
  ('11 Ekim 1922 tarihli Mudanya Ateşkes Antlaşması\'nda "Doğu Trakya\'nın Meriç Nehri\'ne kadar on beş gün içinde Yunan kuvvetlerince boşaltılması ve İtilaf kurulları aracılığıyla otuz gün içinde TBMM jandarmasına teslim edilmesi; İstanbul ve Boğazlar idaresinin de TBMM Hükümeti\'ne bırakılması" maddeleri neyi kanıtlar?', 'Doğu Trakya, İstanbul ve Boğazların silahlı çatışmaya girilmeden diplomatik başarıyla kurtarıldığını ve Osmanlı\'nın hukuken sona erdiğini', ['Kapitülasyonların ve Osmanlı dış borçlarının Mudanya\'da kesin çözüme kavuşturulduğunu', 'Yunanistan\'ın Batı Trakya\'yı savaş tazminatı karşılığında Türkiye\'ye verdiğini', 'İtilaf Devletleri askerlerinin ateşkesin imzalandığı gün İstanbul\'u tamamen boşalttığını'], 'İstanbul ve Boğazlar üzerindeki sivil idarenin TBMM\'ye devredilmesi Osmanlı Devleti\'ni hukuken bitirmiş, Doğu Trakya tek kurşun atılmadan geri alınmıştır.'),
  ('Lozan Antlaşması\'nın azınlıklarla ilgili 40. ve 42. maddelerinde "Türkiye\'deki gayrimüslim azınlıkların kanun önünde tüm Türk vatandaşlarıyla eşit sayılacağı" hükmünün ardından 1926\'da Türk Medeni Kanunu\'nun kabulüyle Rum, Ermeni ve Yahudi cemaatlerinin aile hukuku ayrıcalıklarından kendi istekleriyle vazgeçmesi neyi sağlamıştır?', 'Ülkede çok hukukluluğun sona ererek din ve mezhep farkı gözetmeksizin hukuk birliğinin yerleşmesini ve yabancı müdahale gerekçesinin kalkmasını', ['Gayrimüslim vatandaşların ibadethane ve cemaat okullarının tamamının kapatılmasını', 'Azınlıkların nüfus mübadelesi kapsamına alınarak İstanbul dışına çıkarılmasını', 'Patrikhanenin ekümenik (evrensel) siyasi mahkeme kurma yetkisinin genişletilmesini'], 'Medeni Kanun laik ve eşitlikçi kurallar getirince azınlıkların ayrı cemaat hukukuna ihtiyacı kalmamış, hukuk birliği sağlanmıştır.'),
  ('1 Temmuz 1926\'da yürürlüğe giren Kabotaj Kanunu\'nda "Türkiye sahillerinde bir limandan diğerine mal ve yolcu taşıma, kılavuzluk ve römorkaj hizmetlerini yapma hakkının münhasıran Türk bayrağı çeken gemilere ve Türk vatandaşlarına ait olduğu" hükmü neyi ifade eder?', 'Türk karasularında yabancı şirketlerin deniz ticareti tekeline son verilerek milliyetçilik ilkesinin denizlerde hayata geçirildiğini', ['Boğazlardan uluslararası ticaret gemilerinin geçişinin süresiz olarak yasaklandığını', 'Yabancı devletlerle yapılan tüm deniz ticareti anlaşmalarının iptal edildiğini', 'Ege Denizi\'ndeki On İki Ada\'nın Türkiye egemenliğine geçtiğini'], 'Kabotaj Kanunu, kapitülasyonların deniz taşımacılığındaki kalıntılarını temizleyerek ulusal denizciliği bağımsızlaştırmıştır.'),
  ('1931\'de kurulan Türk Tarih Kurumu\'nun kuruluş direktiflerinde "Türk tarihinin yalnızca Osmanlı hanedan tarihiyle sınırlı olmadığı, Orta Asya\'dan Anadolu\'ya uzanan köklü uygarlık katkılarının arkeolojik ve yazılı kanıtlarla araştırılması gerektiği" vurgusu neyi hedefler?', 'Ümmetçi ve hanedancı tarih anlayışı yerine ulusal özgüveni besleyen bilimsel ve bütüncül bir milli tarih bilinci oluşturmayı', ['Anadolu\'da yaşamış Hitit ve Frig gibi uygarlıkların izlerini müzelerden kaldırmayı', 'Avrupa devletlerinin sömürgecilik faaliyetlerine tarihsel gerekçe üretmeyi', 'Tarih araştırmalarında yabancı kaynakların kullanılmasını tamamen yasaklamayı'], 'Türk Tarih Tezi ve TTK çalışmaları, Batı\'nın Türkleri medeniyet kuramaz gösteren önyargılarını bilimsel araştırmalarla kırmayı ve ulusal kimliği güçlendirmeyi amaçlamıştır.'),
  ('Milletler Cemiyeti adına 1937\'de hazırlanan "Sandler Raporu"nda İskenderun ve Antakya Sancağı için "iç işlerinde tam bağımsız, dış işlerinde Suriye\'ye bağlı, resmi dili Türkçe olan ayrı bir varlık" statüsünün önerilmesi hangi nihai gelişmenin ara basamağı olmuştur?', '1938\'de bağımsız Hatay Devleti\'nin kurulmasının ve 1939\'da Hatay Millet Meclisi kararıyla anavatana katılmasının', ['Hatay\'ın Fransız mandası altında süresiz kalmasının kesinleşmesinin', 'Suriye ile Türkiye arasında geniş çaplı bir sınır savaşının başlamasının', 'Musul ve Kerkük\'ün Hatay karşılığında Türkiye\'ye devredilmesinin'], 'İsveçli diplomat Sandler\'in raporu Hatay\'ın Suriye\'ye terk edilemeyeceğini tescillemiş, önce Hatay Cumhuriyeti kurulmuş ardından kendi meclisinin oy birliğiyle Türkiye\'ye katılmıştır.'),
  ('Büyük İskender\'in Pers seferini anlatan tarihçi Arrianos\'un kroniğinde İskender\'in Mısır\'da Ammon Tapınağı\'nda firavun tacı giydiği, Sus kentinde ise on bin Makedon askerini Pers soylu kadınlarıyla evlendirdiği ve doğuda İskenderiye adlı kütüphaneli şehirler kurduğu aktarılır. Bu uygulamaların tarihsel sonucu ne olmuştur?', 'Yunan (Hellen) uygarlığı ile Doğu uygarlıklarının kaynaşmasından doğan sentez nitelikli Helenistik kültürün ortaya çıkması', ['Yunan şehir devletlerindeki doğrudan demokrasi rejiminin tüm Asya kıtasına yayılması', 'Doğu kültürlerinin tamamen yok edilerek yalnızca Makedon dilinin konuşulması', 'Akdeniz ile Hindistan arasındaki tüm ticaret ve kültür yollarının kapanması'], 'Büyük İskender\'in bilinçli kaynaştırma siyaseti Batı ile Doğu kültürlerini birleştirerek Helenistik uygarlığı doğurmuştur.'),
  ('1789 Fransız İnsan ve Yurttaş Hakları Bildirisi\'nin 1. ve 3. maddelerinde "İnsanlar özgür ve haklar bakımından eşit doğar ve yaşarlar; her türlü egemenliğin özü esas olarak millettedir, hiçbir kurul veya kişi milletten kaynaklanmayan bir otorite kullanamaz" denilmesi hangi rejim anlayışını yıkmıştır?', 'Kralın yetkisini Tanrı\'dan aldığına dayanan mutlak monarşiyi ve soylu-ruhban ayrıcalıklarına dayalı feodal sınıf düzenini', ['Parlamentonun halk oyuyla seçildiği anayasal ve laik cumhuriyet rejimini', 'Sanayi Devrimi ile ortaya çıkan işçi sendikaları ve serbest ticaret ilkelerini', 'Aydınlanma Çağı düşünürlerinin savunduğu güçler ayrılığı ve hukuk devleti kuramını'], '1789 Bildirisi; eşitlik, özgürlük, ulusal egemenlik ve milliyetçilik fikirlerini yayarak mutlakiyetçi imparatorlukları sarsmıştır.'),
  ('Lady Mary Wortley Montagu\'nun 1717-1718 yıllarında Edirne ve İstanbul\'dan İngiltere\'ye gönderdiği mektuplarda "Osmanlı kadınlarının ceviz kabuğu içindeki sıvıyla çocuklara çiçek aşısı (telkih) uyguladığını ve kimsenin çiçek hastalığından ölmediğini" hayranlıkla anlatıp kendi çocuğuna da yaptırması neyin kanıtıdır?', 'Osmanlı toplumunda koruyucu halk hekimliği uygulamalarının on sekizinci yüzyıl başında Batı Avrupa\'dan daha ileri örnekler barındırdığının', ['İngiltere\'nin Lale Devri\'nde Osmanlı hastanelerine çiçek aşısını ilk kez tanıttığının', 'Osmanlı\'da bulaşıcı hastalıklara karşı karantina ve aşılamanın dini fetvayla yasaklandığının', 'Avrupalı elçi eşlerinin Türk aileleriyle görüşmesinin kesinlikle engellendiğinin'], 'Lady Montagu\'nun mektupları çiçek aşısı yönteminin Osmanlı\'dan İngiltere ve Avrupa tıp dünyasına taşınmasında doğrudan köprü rolü oynamıştır.'),
  ('1869 tarihli Maarif-i Umumiye Nizamnamesi\'nde "Eğitimin Sıbyan, Rüştiye, İdadi, Sultani ve Darülfünun şeklinde kademelendirildiği, kız çocukları için kız rüştiyeleri ve kız öğretmen okulu (Darülmuallimat) açılmasının kararlaştırıldığı" görülür. Bu düzenleme hangi gelişmenin göstergesidir?', 'Tanzimat döneminde eğitimin laik-modern bir sistemle taşraya ve kız çocuklarına yayılması için yasal çerçeve çizildiğinin', ['Medreselerin tamamının kapatılarak ülkede Tevhid-i Tedrisat\'ın sağlandığının', 'İlköğretimin yalnızca erkek öğrenciler için paralı hale getirildiğinin', 'Osmanlı Devleti\'nde Latin harflerine dayalı okuryazarlık seferberliğinin başlatıldığının'], '1869 Maarif-i Umumiye Nizamnamesi, Osmanlı modern eğitim teşkilatının ve kızların orta-mesleki eğitime katılımının temel yasal dayanağı olmuştur.'),
  ('1913 Babıali Baskını sonrasında İttihat ve Terakki\'nin iktidarı tam kontrolüne almasıyla çıkarılan "Geçici Aile Kararnamesi (Hukuk-ı Aile Kararnamesi, 1917)"nde evliliklerin devlet memuru ve hakim huzurunda tescil edilmesi ve kadına boşanma şartı koyma hakkı tanınması neyin öncüsüdür?', 'Aile hukukunun devlet denetimine alınmasının ve Cumhuriyet döneminde Medeni Kanun ile sağlanacak kadın hakları reformunun', ['Şer\'i mahkemelerin yetkilerinin genişletilerek çok eşliliğin yasal zorunluluk yapılmasının', 'Kadınlara 1917 yılında milletvekili seçme ve seçilme hakkının verilmesinin', 'Avrupa ülkelerindeki aile yasalarının hiçbir değişiklik yapılmadan tercüme edilmesinin'], '1917 Hukuk-ı Aile Kararnamesi işgal döneminde uzun ömürlü olamasa da evliliği resmi tescile bağlayarak kadın hakları yolunda önemli bir erken adım oluşturmuştur.'),
  ('Mustafa Kemal Paşa\'nın Sakarya Meydan Muharebesi\'nde (Ağustos-Eylül 1921) orduya verdiği "Hattı müdafaa yoktur, sathı müdafaa vardır. O satıh bütün vatandır. Vatanın her karış toprağı vatandaşın kanıyla ıslanmadıkça terk olunamaz" emri, askeri tarih açısından ne ifade eder?', 'Klasik çizgi savunması yerine derinliğine alan savunması taktiğiyle düşman taarruz gücünün kırılarak savaşın kaderinin değiştirildiğini', ['Türk ordusunun savunmayı bırakarak aynı gün İzmir\'e doğru genel taarruza geçtiğini', 'Sakarya Nehri\'nin batısındaki tüm birliklerin Ankara doğusuna geri çekildiğini', 'Yunan ordusunun ikmal hatlarının İngiliz donanması tarafından korunduğunu'], 'Çizgi yarıldığında tüm ordunun çekilmesi yerine her birliğin tutunabildiği noktada direnmesini sağlayan alan savunması doktrini, Sakarya Zaferi\'ni getirmiştir.'),
  ('5 Aralık 1934\'te Teşkilat-ı Esasiye Kanunu\'nun 10. ve 11. maddelerinde yapılan değişiklikle "Yirmi iki yaşını bitiren kadın ve erkek her Türk milletvekili seçmek, otuz yaşını bitiren kadın ve erkek her Türk milletvekili seçilmek hakkına sahiptir" hükmünün getirilmesi neyi sağlamıştır?', 'Kadınların belediye ve muhtarlık haklarının ardından ülke yönetiminde de tam siyasal eşitliğe pek çok Avrupa ülkesinden önce kavuşmasını', ['Türk Medeni Kanunu\'nda kadınlara ilk kez boşanma ve mirasta eşit pay hakkı tanınmasını', 'Tek dereceli seçim sistemine geçilerek seçmen yaşının on sekize indirilmesini', 'Çok partili siyasi hayata geçilerek kadın milletvekillerinin muhalefet partisi kurmasını'], '1930\'da belediye, 1933\'te muhtarlık seçilme hakkını alan Türk kadını, 1934\'te milletvekili seçme ve seçilme hakkıyla Cumhuriyetçilik ve Halkçılık ilkelerini güçlendirmiştir (1935 seçimlerinde 18 kadın mebus Meclis\'e girmiştir).'),
  ('Piri Reis\'in 1513\'te çizdiği Dünya Haritası\'nın kenar notlarında "Kolomb\'un ele geçirilen haritasından, Portekiz ve Arap denizcilerinin portolanlarından yararlandığını" belirtmesi ve 1525\'te sunduğu "Kitab-ı Bahriye"de Akdeniz kıyılarını ayrıntılı tanıtması neyin göstergesidir?', 'Osmanlı denizcilerinin on altıncı yüzyılda açık okyanus keşiflerini ve dünya kartografya gelişmelerini yakından takip ettiğinin', ['Osmanlı donanmasının Amerika kıtasında kalıcı sömürge valilikleri kurduğunun', 'Coğrafi Keşiflerin Akdeniz limanlarının ticari önemini iki katına çıkardığının', 'Piri Reis\'in haritasını yalnızca antik Batlamyus metinlerini kopyalayarak çizdiğinin'], 'Piri Reis\'in farklı kaynakları sentezleyen bilimsel yöntemi, Osmanlı\'nın Coğrafi Keşiflere kayıtsız kalmadığını ve ileri denizcilik bilgisine sahip olduğunu kanıtlar.'),
  ('1935 yılında kabul edilen "Ulusal Bayram ve Genel Tatiller Hakkında Kanun" ile hafta tatilinin cumadan pazara alınması ve bundan önce 1925\'te Miladi Takvim ile 1931\'de metre-kilogram ölçülerinin kabul edilmesi hangi ortak amaca hizmet etmiştir?', 'Uluslararası ticari ve ekonomik ilişkilerde Batı dünyasıyla yaşanan zaman ve ölçü uyumsuzluklarını gidererek entegrasyonu kolaylaştırmaya', ['İç ticarette yöresel arşın, okka ve endaze kullanımını teşvik ederek lonca geleneğini yaşatmaya', 'Avrupa devletlerinin Türkiye üzerindeki gümrük denetimini yeniden başlatmaya', 'Ülke içindeki dini bayram tatillerinin tamamını yürürlükten kaldırmaya'], 'Takvim, saat, rakam, ölçü ve hafta tatili inkılapları hem ülke içindeki ölçü karmaşasını bitirmiş hem de Türkiye\'nin dünya ekonomisiyle uyumunu sağlamıştır.'),
  ('Bir araştırma ekibi gittiği yörede yazların sıcak ve kurak, kışların ılık ve yağışlı geçtiğini; kızılçam ormanlarının tahribiyle gelişen bodur çalıların baskın olduğunu ve kalkerli arazide demir oksitçe zengin kırmızı renkli topraklar üzerinde zeytin ile turunçgil tarımı yapıldığını gözlemlemiştir. Bu yörenin coğrafi özellikleri dikkate alındığında kırsal konutlarda hangi yapı malzemesinin yaygın olması beklenir?', 'Taş malzeme', ['Ahşap kütükler', 'Kerpiç bloklar', 'Saz ve kamış demetleri'], 'Akdeniz iklim bölgesinde kalkerli (kireç taşlı) arazilerin yaygınlığı ve terra rossa topraklarının varlığı nedeniyle kırsal meskenlerde en çok taş malzeme tercih edilir.'),
  ('İlkbahar yağışlarıyla yeşeren, yaz kuraklığıyla sararan kısa boylu ot topluluklarının yaygın olduğu iç kesimlerde, organik madde yönünden orta düzeyde olan kestane ve kahverengi step toprakları görülür. Bu doğal ortam koşullarında en uygun geleneksel ekonomik faaliyet ikilisi aşağıdakilerden hangisidir?', 'Tahıl tarımı ve küçükbaş hayvancılık', ['Çeltik üretimi ve büyükbaş mera hayvancılığı', 'Çay yetiştiriciliği ve ipek böcekçiliği', 'Muz tarımı ve arıcılık faaliyetleri'], 'Ilıman karasal (step) iklim bölgelerinde bozkır bitki örtüsü ve step toprakları üzerinde buğday-arpa gibi tahıl tarımı ile koyun-keçi odaklı küçükbaş hayvancılık gelişmiştir.'),
  ('Yıl boyunca sıcak ve nemli olan Ekvatoral iklim bölgesinde, aşırı yıkanma nedeniyle mineral ve humus bakımından fakirleşmiş kiremit kırmızısı laterit topraklar yaygındır. Gür yağmur ormanlarıyla kaplı olmasına rağmen bu bölgede alçak kesimlerin yerleşme açısından seyrek nüfuslu olmasının temel nedeni nedir?', 'Yüksek sıcaklık ve nemin bunaltıcı etkisi ile gür ormanların yaşamı zorlaştırması', ['Şiddetli kış donlarının tarımsal üretim süresini birkaç ayla sınırlandırması', 'Yüzey sularının yetersizliği nedeniyle içme suyu temininin imkansız olması', 'Toprakların aşırı kireçli yapısının bina temellerinde çökmelere yol açması'], 'Ekvatoral bölgede 0-1000 metre arasındaki alçak kesimler yüksek sıcaklık, aşırı nem, bataklıklar ve gür orman örtüsü nedeniyle insan yaşamına elverişsizdir; yerleşmeler 1000 metrenin üzerine çıkar.'),
  ('Kurak ve yarı kurak iklim bölgelerinde yağış azlığı ve su kaynaklarının sınırlı olması nedeniyle kırsal kesimde insanlar kuyu, çeşme veya akarsu boylarında bir arada yaşamak zorundadır. Bu durum aşağıdaki yerleşme dokularından hangisinin ortaya çıkmasına doğrudan neden olur?', 'Toplu yerleşme', ['Dağınık yerleşme', 'Göçebe çadır yerleşmesi', 'Sahil boyu ikincil konut yerleşmesi'], 'Su kaynaklarının kıt, arazinin ise genellikle düz olduğu kurak ve yarı kurak bölgelerde (örneğin İç Anadolu ve Güneydoğu Anadolu) evler su kaynağının etrafında toplanarak toplu yerleşmeleri oluşturur.'),
  ('Güneydoğu Anadolu\'da Fırat ve Dicle nehirleri üzerinde kurulan barajlarla birlikte sulamalı tarıma geçilen ovalarda, daha önce kuru tarımla yetiştirilen kırmızı mercimek ve buğday alanları daralmıştır. Sulama imkanlarının artmasıyla bu ovalarda hangi ürünün ekim alanında ve buna bağlı sanayi tesislerinde büyük bir artış yaşanmıştır?', 'Pamuk üretimi ve tekstil-çırçır sanayisi', ['Çay tarımı ve paketleme fabrikaları', 'Fındık üretimi ve çikolata sanayisi', 'Kayısı yetiştiriciliği ve meyve kurutma tesisleri'], 'GAP ile sulamanın yaygınlaştığı Şanlıurfa-Harran gibi yüksek yaz sıcaklığına sahip ovalarda pamuk üretimi hızla birinci sıraya yerleşmiş, buna bağlı çırçır, iplik ve tekstil sanayisi gelişmiştir.'),
  ('Yıl boyu soğuk olan, toprağın büyük bölümünün donmuş halde (permafrost) bulunduğu ve yalnızca birkaç aylık kısa yaz döneminde yüzeyin çözülmesiyle yosun ile likenlerin yeşerdiği bölge aşağıdakilerden hangisidir?', 'Tundra bölgesi', ['Savan bölgesi', 'Step bölgesi', 'Maki bölgesi'], 'Kutup altı iklimde görülen permafrost (donmuş toprak) ve kısa yazda çözülen bataklık yüzeyde yetişen yosun-liken topluluğu tundra biyomunun karakteristik özelliğidir.'),
  ('Batı Avrupa kıyılarında ılıman okyanusal iklimin etkisiyle her mevsim yağışlı bir hava hakimdir, kışlar ılık ve yazlar serin geçer. Kahverengi orman topraklarının yaygın olduğu bu bölgede yer şekillerinin de sade olması ulaşım ve tarımı nasıl etkilemiştir?', 'Akarsu rejimlerinin düzenli ve yatak eğimlerinin az olması nehir içi ulaşımı geliştirmiş, modern tarım ve hayvancılık yoğunlaşmıştır.', ['Yaz kuraklığının şiddetli olması nedeniyle pamuk ve turunçgil tarımı temel geçim kaynağı haline gelmiştir.', 'Şiddetli kış donları nedeniyle karayolu ve demiryolu ulaşımı yılın yarısında tamamen durma noktasına gelmiştir.', 'Toprakların aşırı tuzlu olması tarımı engellemiş, nüfus yalnızca yüksek dağ eteklerinde toplanmıştır.'], 'Batı Avrupa\'da ılıman okyanusal iklim ve düz yer şekilleri sayesinde akarsular düzenli rejimli ve ulaşıma elverişlidir; intansif tarım ve ahır hayvancılığı çok gelişmiştir.'),
  ('Akarsuların aşındırdığı malzemeleri eğimin azaldığı vadi tabanlarında ve denize döküldüğü ağız kısımlarında biriktirmesiyle oluşan, horizonları belirgin olmayan ancak mineralce çok zengin toprak tipi aşağıdakilerden hangisidir?', 'Alüvyal topraklar', ['Terra rossa topraklar', 'Podzol topraklar', 'Tundra topraklar'], 'Akarsuların taşıyıp biriktirdiği dış kuvvet kökenli azonal topraklar alüvyal topraklardır; katmanlaşma (horizon) görülmez fakat çok verimlidirler.'),
  ('Ayçiçeği, yetişme döneminde nem ve yağış, olgunlaşma ve hasat döneminde ise güneşli ve kurak bir hava isteyen yağ bitkisidir. Türkiye\'de bu bitkinin en yoğun üretildiği Ergene Havzası\'nda, tarımsal üretime bağlı olarak aşağıdaki sanayi kollarından hangisinin yaygınlaşması doğrudan bu nedenselliğin sonucudur?', 'Bitkisel sıvı yağ ve yem sanayisi', ['Konserve balık ve deniz ürünleri sanayisi', 'İpekli dokuma ve halıcılık sanayisi', 'Kereste ve mobilya imalat sanayisi'], 'Ergene Havzası\'nın yarı nemli iklimi ve hafif engebeli verimli toprakları ayçiçeği tarımına çok uygundur; hammaddeye yakınlık ilkesiyle bölgede bitkisel yağ ve küspeden yem üreten fabrikalar yoğunlaşmıştır.'),
  ('Çöl iklim bölgelerinde yıllık yağış miktarı 200 mm\'nin altındadır ve günlük sıcaklık farkları çok yüksektir. Fiziksel (mekanik) çözünmenin şiddetli olduğu bu alanlarda su kaybını önlemek için yaprakları dikene dönüşmüş ve kök sistemleri çok gelişmiş hangi bitki topluluğu görülür?', 'Kaktüsler ve kurakçıl çalılar', ['Geniş yapraklı yayvan ağaçlar', 'Uzun boylu dağ çayırları', 'Kızılçam ve fıstık çamı toplulukları'], 'Çöllerde kuraklığa uyum sağlamış, su depolayan gövdeli, diken yapraklı ve derin köklü kserofit (kurakçıl) bitkiler ile kaktüsler görülür.'),
  ('Eğimli yamaçlarda orman örtüsünün tahrip edilmesi ve tarlaların eğim yönüne paralel sürülmesi, sağanak yağışlarla birlikte verimli üst toprağın süpürülmesine yol açar. Bu durumun kırsal yerleşmeler üzerindeki en belirgin sosyoekonomik sonucu aşağıdakilerden hangisidir?', 'Tarımsal verimin düşmesiyle geçim sıkıntısının başlaması ve kentlere doğru göçün hızlanması', ['Köylerde tarıma dayalı büyük sanayi holdinglerinin hızla kurulması', 'Kırsal kesimde tarım işçisi açığının büyümesiyle kentten köye tersine göç başlaması', 'Birim alandan alınan ürün miktarının hiçbir girdi kullanılmadan iki katına çıkması'], 'Erozyonla verimli üst toprağın (A horizonu) kaybedilmesi tarımsal verimi düşürür, kırsal yoksulluğu artırır ve kırdan kente göçü tetikler.'),
  ('Kışların çok soğuk ve kar yağışlı, yazların ise kısa ve serin geçtiği yüksek dağlık bölgelerde çatılar kar yükünü taşıyabilmesi için dik eğimli yapılır. Orman varlığının da zengin olduğu bu tür kırsal alanlarda geleneksel konut yapımında en çok tercih edilen malzeme hangisidir?', 'Ahşap', ['Kerpiç', 'Alçı taşı', 'Saz ve kamış'], 'Orman örtüsünün gür olduğu nemli ve karlı dağlık bölgelerde (örneğin Karadeniz yayla ve dağ köyleri, Alpler, İskandinavya) dik çatılı ahşap meskenler yaygındır.'),
  ('Zeytin ağacı derin kök sistemi ve mumsu yapraklarıyla yaz kuraklığına dayanıklıdır; ancak kış aylarında sıcaklığın -5 °C\'nin altına düştüğü yerlerde yetişemez. Bu bilgiye dayanarak Türkiye\'de zeytin tarımının İç Anadolu ve Doğu Anadolu bölgelerinde yapılamamasının temel nedeni aşağıdakilerden hangisidir?', 'Yükselti ve karasallığa bağlı olarak kış sıcaklıklarının çok düşük olması', ['Yaz aylarında güneşlenme süresinin ve sıcaklığın yetersiz kalması', 'Bölge topraklarında demir ve kireç minerallerinin hiç bulunmaması', 'İlkbahar mevsiminde konveksiyonel yağışların hiç görülmemesi'], 'Zeytin kış ılıklığı ister; İç ve Doğu Anadolu\'da yükselti ve karasallık nedeniyle kışın şiddetli don olayları yaşandığından zeytin yetişemez.'),
  ('Killi ve kireçli ana materyal üzerinde, kurak mevsimde kuruyup büzülerek derin çatlaklar oluşturan, yağışlı mevsimde ise su alıp şişerek çatlakları kapanan ve "dönen toprak" ya da "taş doğuran toprak" olarak bilinen toprak tipi hangisidir?', 'Vertisol topraklar', ['Laterit topraklar', 'Regosol topraklar', 'Kalsimorfik rendzina dışındaki çöl toprakları'], 'Eski göl tabanlarında (örneğin Trakya/Ergene ve Muş Ovası) killi-kireçli depolarda oluşan, kurak dönemde çatlayıp içine dökülen malzemeyi yağışlı dönemde şişerek yukarı iten topraklar vertisol (taş doğuran/karakepir) topraklardır.'),
  ('İpek böcekçiliği, tırtılların tek besin kaynağı olan dut ağacının yetişebildiği iklim bölgelerinde yapılabilen geleneksel bir faaliyettir. Geçmişte Bursa, Bilecik ve Diyarbakır çevresinde çok yaygın olan yaş koza üretiminin zamanla gerilemesindeki en belirleyici sanayi ve pazar etkeni nedir?', 'Tekstil sanayisinde daha ucuz olan sentetik (yapay) ipek ve polyester liflerin yaygınlaşması', ['Türkiye\'de iklim değişikliği nedeniyle dut ağaçlarının tamamının kuruması', 'İpekli kumaşların karayolu ile taşınmasının yasal olarak yasaklanması', 'Dut bahçelerinin tamamının taş kömürü maden ocaklarına dönüştürülmesi'], 'Doğal ipek üretimi yoğun emek ister; sanayide ucuz suni/sentetik liflerin üretilmesi ve zirai ilaçlamaların böceklere zarar vermesi geleneksel ipek böcekçiliğini geriletmiştir.'),
  ('Akarsu boylarında, karayolu kenarlarında veya dar kıyı şeritlerinde evlerin bir hat boyunca uzanmasıyla oluşan kırsal ya da kentsel yerleşme dokusuna ne ad verilir?', 'Çizgisel yerleşme', ['Dairesel yerleşme', 'Küme yerleşme', 'Noktasal yerleşme'], 'Akarsu vadisi, kıyı şeridi veya ulaşım yolu boyunca uzunlamasına dizilen yerleşmelere çizgisel (hat) yerleşme denir.'),
  ('Kış mevsiminin uzun ve sert geçtiği, kar kalınlığının fazla olduğu Doğu Anadolu Bölgesi\'nde ulaşım ağı ile yer şekilleri arasındaki ilişki incelendiğinde karayolu ve demiryolu hatlarının hangi uzanışı gösterdiği görülür?', 'Dağ sıraları arasındaki doğu-batı yönlü tektonik olukları ve akarsu vadilerini izler.', ['Kuzey-güney doğrultusunda en yüksek dağ zirvelerini dik olarak keser.', 'Yer şekillerinden bağımsız olarak tam ızgara (satranç tahtası) planıyla uzanır.', 'Yalnızca kapalı göl havzalarının tabanlarında dairesel halkalar çizer.'], 'Doğu Anadolu\'da dağlar genel olarak doğu-batı uzanışlıdır; ulaşım maliyetini düşürmek ve eğimden kaçınmak için yollar Pasinler-Erzurum-Erzincan veya Elazığ-Malatya gibi doğu-batı yönlü tektonik oluk ve vadileri takip eder.'),
  ('Bakır cevheri doğadan çıkarıldığında tenör (saf metal) oranı düşük ve atık kayaç oranı yüksek bir madendir; bu nedenle taşınma maliyetini azaltmak için izabe (eritme) tesisleri genellikle madene yakın kurulur. Ancak Samsun\'da bakır madeni çıkarılmamasına rağmen büyük bir bakır işleme tesisinin kurulmuş olması hangi faktörle açıklanır?', 'Liman ve ulaşım olanaklarının gelişmiş olması', ['Samsun deltalarında bakır eritmek için gereken volkanik lav sıcaklığının bulunması', 'Bölgede tarımsal iş gücünün olmaması nedeniyle halkın yalnızca madencilikte uzmanlaşması', 'Bakır fabrikalarının çalışması için çeltik kabuklarının yakıt olarak zorunlu olması'], 'Murgul ve Ergani\'de bakır tesisleri hammaddeye yakın kurulmuşken, Samsun\'daki Karadeniz Bakır İşletmeleri liman ve ulaşım (pazarlama/sevkiyat) avantajı nedeniyle kurulmuştur.'),
  ('Toprağın yalnız dış kuvvetlerce taşınmış değil, bulunduğu yerdeki ana kayanın iklim ve canlıların etkisiyle ayrışması sonucu oluşan, tüm horizonları (A, B, C, D) belirgin yerli toprak grubuna ne ad verilir?', 'Zonal topraklar', ['Azonal topraklar', 'İntrazonal topraklar', 'Alüvyal ve kolüvyal topraklar'], 'Bulunduğu bölgenin iklim ve bitki örtüsü özelliklerini yansıtan, A-B-C-D horizonları tam gelişmiş yerli topraklara zonal topraklar (terra rossa, çernozyom, podzol, laterit, kahverengi orman vb.) denir.'),
  ('Zeytin, incir, üzüm, haşhaş, tütün ve pamuk gibi ürünlerin birçoğunda üretim payı yüksek olan Kıyı ve İç Batı Ege\'de, tarımsal çeşitliliğin bu kadar fazla olmasını sağlayan coğrafi etkileşim aşağıdakilerden hangisidir?', 'Kıyıdaki Akdeniz ikliminden iç kesimdeki ılıman karasal iklime kademeli geçiş yaşanması ve verimli çöküntü ovalarının varlığı', ['Bölgenin tamamında her mevsim yağışlı okyanusal iklimin ve laterit toprakların görülmesi', 'Yükseltinin batıdan doğuya doğru azalması ve don olaylarının kıyıda daha sık yaşanması', 'Tarımsal alanların tamamında yalnızca geleneksel kara saban ve kuru tarım yöntemlerinin kullanılması'], 'Ege\'de dağların kıyıya dik uzanması kıyıdaki Akdeniz ikliminden İç Batı Anadolu\'daki geçiş iklimine kademeli bir değişim yaratır; kıyı grabenlerinde zeytin-incir-pamuk, iç platolarda haşhaş-şekerpancarı-tahıl yetişir.'),
  ('Dağ eteklerinde eğimin azaldığı yerlerde sel sularının ve yer çekiminin etkisiyle biriken iri ve ince unsurlu malzemeler üzerinde oluşan, bahçe ve bağ tarımına çok elverişli taşlı-kumlu toprak tipi hangisidir?', 'Kolüvyal topraklar', ['Halomorfik topraklar', 'Hidromorfik topraklar', 'Çernozyom topraklar'], 'Eğimli yamaçlardan inen malzemenin dağ eteklerinde (birikinti konisi ve yelpazelerinde) birikmesiyle oluşan süzek, havalandırması iyi ve bağ-bahçe tarımına uygun azonal topraklar kolüvyal topraklardır.'),
  ('Güneydoğu Anadolu Bölgesi\'nin batısında (Gaziantep ve Şanlıurfa-Birecik çevresi) zeytin ve antepfıstığı bahçeleri geniş yer kaplarken, bölgenin doğusuna (Diyarbakır-Siirt-Batman hattına) doğru gidildikçe zeytin ağaçları ortadan kalkmaktadır. Bu değişimin temel iklimsel nedeni nedir?', 'Batıdan doğuya doğru gidildikçe Akdeniz iklim etkisinin zayıflaması ve karasallığın artması', ['Doğuya gidildikçe yükseltinin deniz seviyesinin altına düşmesi', 'Bölgenin doğusunda her mevsim şiddetli Muson yağmurlarının görülmesi', 'Batı kesimde toprakların tamamen donmuş tundra yapısında olması'], 'Gaziantep-Kilis-Birecik çevresinde Akdeniz ikliminin etkisi sokulabildiği için kışlar nispeten ılıktır ve zeytin yetişir; doğuya doğru karasallık ve kış donları arttığı için zeytin yetişemez.'),
  ('Kurak ve yarı kurak bölgelerde kapalı havza tabanlarında buharlaşma sonucunda suda çözünmüş tuz ve karbonatların toprak yüzeyinde birikmesiyle oluşan, tarıma elverişsiz çorak topraklara ne ad verilir?', 'Halomorfik (tuzlu-alkali) topraklar', ['Laterit topraklar', 'Kahverengi orman toprakları', 'Çernozyom topraklar'], 'Kurak bölgelerde (örneğin Tuz Gölü çevresi ve Konya Ovası\'nın drenajı bozuk kesimleri) şiddetli buharlaşmayla tuzların yüzeyde biriktiği topraklar intrazonal gruptaki halomorfik (tuzlu) topraklardır.'),
  ('Bir akarsuyun denize döküldüğü yerde delta ovası oluşabilmesi için akarsuyun bol alüvyon taşıması, kıyının sığ olması ve kıyıda güçlü akıntı veya gelgit olmaması gerekir. Karadeniz kıyısında Kızılırmak ve Yeşilırmak deltalar oluştururken, Sakarya Nehri\'nin ağzında büyük bir delta gelişememesinin temel nedeni nedir?', 'Kıyıda etkili olan güçlü akıntıların ve dalgaların biriken alüvyonları dağıtması', ['Sakarya Nehri\'nin geçtiği bölgelerde hiç toprak örtüsünün bulunmaması', 'Karadeniz\'de okyanus kıyılarından daha büyük gelgit genliğinin yaşanması', 'Nehrin ağız kısmında aktif bir fay hattının suları yer altına çekmesi'], 'Sakarya ağzında Karadeniz kıyı akıntılarının güçlü olması (boğaz akıntısına yönelim) ve havzadaki barajlar nedeniyle kıyıda belirgin bir delta çıkıntısı oluşamamıştır.'),
  ('Kırsal yerleşmelerde nüfusun büyüklüğüne ve idari yapısına göre yapılan sınıflandırmada; cami, okul, otlak ve baltalık orman gibi ortak malları bulunan en küçük idari kır yerleşmesi birimi aşağıdakilerden hangisidir?', 'Köy', ['Mezra', 'Kom', 'Ağıl'], 'Türkiye\'de köy kanununa göre cami, okul, yaylak, baltalık gibi ortak malları bulunan ve muhtarlıkla yönetilen en küçük idari kır yerleşmesi köydür; mezra, kom ve ağıl köy altı yerleşmeleridir.'),
  ('Yüksek dağların zirvelerinde kalıcı kar sınırının altında, orman üst sınırının ise üzerinde yer alan ve yaz boyu eriyen kar sularıyla beslenen kısa boylu ot topluluklarına ne ad verilir?', 'Alpin (dağ) çayırları', ['Garig (frigana) çalıları', 'Psödomaki', 'Galeri ormanları'], 'Orman üst sınırı ile kalıcı kar sınırı arasındaki soğuk kuşakta yetişen ot formasyonuna Alpin (dağ) çayırları denir.'),
  ('Petrol rafinerileri ham petrolün işlenerek benzin, motorin, jet yakıtı, LPG ve asfalt gibi ürünlere dönüştürüldüğü tesislerdir. Türkiye\'deki Batman, İzmir (Aliağa), Kocaeli (İzmit-TÜPRAŞ) ve Kırıkkale (Orta Anadolu) rafinerilerinden hangisi kuruluş yeri açısından doğrudan "yerli hammadde kaynağına yakınlık" ilkesiyle diğerlerinden ayrılır?', 'Batman Rafinerisi', ['Kocaeli (İzmit) Rafinerisi', 'İzmir (Aliağa) Rafinerisi', 'Kırıkkale Rafinerisi'], 'Batman Rafinerisi Raman ve Garzan\'dan çıkarılan yerli ham petrolü işlemek üzere hammaddeye yakın kurulmuştur; İzmit ve Aliağa deniz ulaşımı/pazar, Kırıkkale ise güvenlik ve İç Anadolu pazarına dağıtım amacıyla kurulmuştur.'),
  ('Jeotermal enerji, yer kabuğunun kırıklı (faylı) olduğu bölgelerde yer altına sızan suların magmanın etkisiyle ısınıp buhar veya sıcak su halinde yüzeye çıkmasıyla elde edilir. Türkiye\'de jeotermal elektrik santrallerinin tamamına yakınının Denizli, Aydın ve Manisa gibi Batı Anadolu illerinde toplanmış olmasının temel nedeni nedir?', 'Horst-graben sistemini oluşturan genç kırıklı (faylı) jeolojik yapının bu bölgede çok yoğun olması', ['Batı Anadolu\'da yıllık güneşlenme süresinin ve yaz sıcaklığının çok yüksek olması', 'Menderes nehirlerinin yatak eğiminin yüksek ve akış hızının fazla olması', 'Bölgede geniş linyit ve asfaltit yataklarının yüzeye yakın bulunması'], 'Ege Bölgesi\'ndeki kırıklı (horst-graben) yapı boyunca zengin sıcak su ve buhar kaynakları yüzeye çıkar; bu nedenle Sarayköy (Denizli), Germencik (Aydın) ve Alaşehir (Manisa) jeotermal enerjinin merkezidir.'),
  ('Toprağın oluşumunda ana kayanın sertliği ve mineral yapısı önemli rol oynar; ancak yumuşak kireç taşı (marn) veya killi şistler üzerinde oluşan, altında koyu renkli organik A horizonu ve hemen altında kireçli beyaz C horizonu bulunan intrazonal toprak hangisidir?', 'Rendzina topraklar', ['Podzol topraklar', 'Laterit topraklar', 'Tundra topraklar'], 'Yumuşak kireç taşları üzerinde oluşan, üst kısmı koyu renkli (humuslu) alt kısmı ise kireçce zengin beyazımsı kalsimorfik (intrazonal) topraklara rendzina denir.'),
  ('Fındık ağacı kışları ılık geçen, yıllık yağışın bol ve mevsimlere düzenli dağıldığı, yaz kuraklığının görülmediği Karadeniz ikliminin tipik ürünüdür. Türkiye dünya fındık üretiminin büyük çoğunluğunu karşılarken, Ordu ve Giresun\'un ardından Sakarya ve Düzce ovalarının da üretimde üst sıralara çıkmasını sağlayan faktör nedir?', 'Karadeniz iklim etkisinin Batı Karadeniz ve Doğu Marmara\'da da görülmesi, arazinin daha az eğimli olması ve İstanbul pazarına yakınlık', ['Sakarya ve Düzce\'de Akdeniz ikliminin görülmesi ve yazların çok kurak geçmesi', 'Doğu Karadeniz\'deki tüm fındık bahçelerinin sökülerek yerine pamuk ekilmesi', 'Fındık ağacının yalnızca tuzlu bataklık topraklarında yüksek verim vermesi'], 'Karadeniz iklim kuşağı Marmara\'nın kuzey ve doğusuna (Sakarya, Kocaeli, Düzce) kadar uzanır; burada iklim uygun olduğu gibi arazi Ordu-Giresun\'a göre daha düzdür ve büyük pazarlara/sanayiye çok yakındır.'),
  ('Kırsal kesimde tarla ve bahçelerin köyden uzakta olması veya hayvancılık faaliyetlerinin yürütülmesi amacıyla kurulan, bir ya da birkaç ailenin yaşadığı ve zamanla sürekli yerleşmeye dönüşebilen köy altı yerleşmelerinden "mezra" ve "kom" Türkiye\'de en yaygın hangi bölgelerde görülür?', 'Doğu Anadolu ve Güneydoğu Anadolu', ['Marmara ve Kıyı Ege', 'Batı Karadeniz ve Trakya', 'Yalnızca Antalya ve Mersin kıyıları'], 'Mezra (tarım + hayvancılık, çoğunlukla kalıcı) ve kom (hayvancılık odaklı, Doğu Anadolu\'ya özgü) engebeli arazi ve aşiret/aile toprak mülkiyeti yapısına bağlı olarak en çok Doğu ve Güneydoğu Anadolu\'da görülür.'),
  ('Mobilya sanayisi, hem kereste/sunta/MDF gibi orman ürünlerine hem de sünger, kumaş, metal ve boya gibi yan sanayi kollarına ihtiyaç duyan, tüketici pazarına yakınlığın da büyük avantaj sağladığı bir sektördür. Türkiye\'de Bursa (İnegöl), Kayseri, Ankara (Siteler), İstanbul ve İzmir\'in önemli mobilya üretim merkezleri olması hangi faktörlerin birleşimiyle açıklanır?', 'Hammadde temin kolaylığı, gelişmiş ulaşım-pazarlama ağı, nitelikli zanaatkar/iş gücü birikimi ve büyük tüketim merkezlerine yakınlık', ['Bu şehirlerin tamamının Türkiye\'nin en gür yağmur ormanlarının tam ortasında yer alması', 'Mobilya üretiminin yalnızca deniz yoluyla ithal edilen tropikal ağaçlarla yapılabilmesi', 'Devletin diğer illerde marangozluk ve mobilya atölyesi açılmasını yasaklaması'], 'İnegöl ve Batı Karadeniz yakınlığı hammadde avantajı sağlarken; Kayseri, Ankara, İstanbul ve İzmir ulaşım kavşağı, yan sanayi (tekstil, kimya, metal), sermaye ve büyük pazar avantajıyla mobilya üssü olmuştur.'),
  ('Tarih boyunca Çin\'den başlayarak Orta Asya bozkırlarını ve Anadolu\'yu (veya Karadeniz kuzeyini) geçip Avrupa\'ya uzanan, geçtiği güzergahlarda kervansarayların ve ticaret kentlerinin büyümesini sağlayan kadim kara ticaret yolu hangisidir?', 'İpek Yolu', ['Kral Yolu', 'Kehribar Yolu', 'Kürk Yolu'], 'Doğu ile Batı arasında ipek, porselen, kağıt ve kültür alışverişini sağlayan ve günümüzde "Demir İpek Yolu / Kuşak ve Yol Girişimi" ile canlandırılan tarihi güzergah İpek Yolu\'dur.'),
  ('Boru hattı taşımacılığı; sıvı ve gaz halindeki enerji kaynaklarının (ham petrol, doğalgaz) üretildiği noktadan tüketim merkezlerine veya limanlara kesintisiz aktarılmasını sağlar. Diğer kara ulaşım türleriyle karşılaştırıldığında boru hatlarının en önemli üstünlüğü aşağıdakilerden hangisidir?', 'İlk yatırım maliyeti yüksek olsa da işletme maliyetinin düşük olması, iklim koşullarından etkilenmeden güvenli, hızlı ve yüksek kapasiteli taşıma sağlaması', ['Katı maden cevherleri, tahıl ve canlı hayvan taşımacılığında en yaygın kullanılan sistem olması', 'İstenildiği anda güzergahının birkaç saat içinde başka bir ülkeye kaydırılabilmesi', 'Hiçbir pompa istasyonuna ve bakıma ihtiyaç duymadan sonsuza dek çalışabilmesi'], 'Boru hatları kurulduktan sonra 7/24 kesintisiz, hava muhalefetinden etkilenmeden, tanker kazası/trafik riski olmadan düşük birim işletme maliyetiyle yüksek hacimli petrol ve gaz taşır.'),
  ('Bitki örtüsünün çok cılız olduğu kurak ve yarı kurak bölgelerde, rüzgarın gevşek ince kum ve toz boyutundaki toprakları havalandırarak çok uzak mesafelere taşıması ve biriktirmesiyle oluşan verimli toprak tipi aşağıdakilerden hangisidir?', 'Lös topraklar', ['Moren topraklar', 'Alüvyal topraklar', 'Kolüvyal topraklar'], 'Rüzgarların taşıyıp biriktirdiği ince unsurlu azonal topraklara lös, buzulların taşıyıp biriktirdiği karışık unsurlu topraklara ise moren denir.'),
  ('Ekstansif (yaygın/ilkel) tarım yönteminin uygulandığı bölgelerde sulama, gübreleme ve ıslah edilmiş tohum kullanımı yetersizdir. Bu yöntemin baskın olduğu bir ovada buğday üretiminin bir yıl çok yüksek, ertesi yıl ise çok düşük gerçekleşmesinin temel nedeni nedir?', 'Tarımsal üretimin doğrudan doğal iklim koşullarına (özellikle ilkbahar yağışlarının miktar ve zamanına) bağımlı olması', ['Çiftçilerin bir yıl buğday ekip ertesi yıl tarlaları sanayi arsasına dönüştürmesi', 'Buğday bitkisinin iki yılda bir meyve veren çok yıllık bir ağaç olması', 'Uluslararası piyasalarda buğday fiyatlarının çift yıllarda sıfırlanması'], 'Ekstansif (kuru/geleneksel) tarımda sulama olmadığından ilkbahar yağışları bol ve zamanında düşerse üretim artar, kurak geçerse üretim sert biçimde düşer (iklime bağımlılık yüksektir).'),
  ('Deniz, göl ve akarsulardan avcılık veya yetiştiricilik (kültür balıkçılığı) yoluyla su ürünleri elde edilmesi ekonomik faaliyet kollarından hangisinin kapsamında yer alır?', 'Birincil ekonomik faaliyetler (Tarım/Avcılık/Toplayıcılık)', ['İkincil ekonomik faaliyetler (Sanayi/İmalat)', 'Üçüncül ekonomik faaliyetler (Hizmet/Lojistik)', 'Dördüncül ekonomik faaliyetler (Bilişim/Ar-Ge)'], 'Doğadan doğrudan hammadde ve gıda elde etmeye dayanan tarım, hayvancılık, ormancılık, balıkçılık ve madencilik birincil (primer) ekonomik faaliyetlerdir.'),
  ('Seramik, porselen ve çini sanayisi; kaolen, kuvars ve feldspat gibi özel kil ve toprak hammaddelerini yüksek ısıda pişirerek yapı malzemesi ve eşya üreten bir sanayi koludur. Türkiye\'de Kütahya, Bilecik (Bozüyük), Çanakkale (Çan) ve Eskişehir\'in bu sanayi kolunda marka haline gelmesinin temel nedeni nedir?', 'Zengin ve kaliteli kil/kaolen yataklarına sahip olmaları, tarihsel çinicilik zanaat mirası ve Batı Anadolu\'daki büyük inşaat pazarlarına yakınlık', ['Bu illerin tamamının açık deniz kıyısında büyük konteyner limanlarına sahip olması', 'Seramik üretiminin yalnızca Akdeniz iklimindeki maki çalılarının külüyle yapılabilmesi', 'Bölgede başka hiçbir tarım veya hayvancılık faaliyetinin yürütülememesi'], 'Kütahya-İznik-Bilecik-Çanakkale hattında hem birinci sınıf seramik killeri (hammadde) ve köklü geleneksel ustalık hem de İstanbul-İzmir-Ankara üçgenindeki büyük pazara ve ulaşım yollarına yakınlık birleşmiştir.'),
  ('Şehirlerin ortaya çıkışında ve büyümesinde tarım, sanayi, maden, ulaşım, yönetim, din, eğitim ve turizm gibi işlevlerden biri ya da birkaçı öne çıkar. Buna göre Mekke, Kudüs, Vatikan ve Lhasa şehirlerinin küresel ölçekte tanınmasını sağlayan birincil kentsel fonksiyon hangisidir?', 'Dini fonksiyon', ['Madencilik fonksiyonu', 'Ağır sanayi fonksiyonu', 'Askeri garnizon fonksiyonu'], 'Mekke (İslam), Vatikan (Katolik Hristiyanlık), Kudüs (üç semavi din) ve Lhasa (Tibet Budizmi) dini merkez fonksiyonuyla öne çıkan şehirlerdir.'),
  ('Brasilia (Brezilya), Canberra (Avustralya), İslamabad (Pakistan) ve Ankara (Türkiye) şehirlerinin yirminci yüzyılda ülkelerinin siyasi başkentleri olarak seçilmeleri ve hızla büyümeleri hangi kentsel fonksiyonun dönüştürücü gücüne örnektir?', 'İdari (yönetim) fonksiyon', ['Liman ve deniz ticareti fonksiyonu', 'Kış sporları turizmi fonksiyonu', 'Balıkçılık ve ormancılık fonksiyonu'], 'Ankara, Brasilia, Canberra veAstana/İslamabad gibi şehirler, siyasi ve idari bir kararla başkent ilan edildikten sonra devlet kurumları, elçilikler ve kamu yatırımlarıyla hızla büyüyen yönetim kentleridir.'),
  ('Sanayi Devrimi ilk olarak 18. yüzyılın ikinci yarısında İngiltere\'de (Manchester ve çevresinde) buhar gücünün dokuma makinelerine uygulanması ve taş kömürünün demir eritmede kullanılmasıyla başlamıştır. Bu süreçte kırsaldan sanayi kentlerine yönelen büyük göç dalgası nüfusun sektörel dağılımını nasıl değiştirmiştir?', 'Tarım (birincil) sektöründe çalışanların oranı azalırken sanayi (ikincil) ve ardından hizmet (üçüncül) sektörlerinin payı hızla artmıştır.', ['Hizmet ve sanayi sektörleri tamamen kapanmış, nüfusun tamamı çiftçiliğe dönmüştür.', 'Şehir nüfus oranı düşerken köy nüfus oranı %90\'ın üzerine çıkmıştır.', 'Buhar makineleri yalnızca kırsal yaylalarda kurulduğu için göç dağlara doğru gerçekleşmiştir.'], 'Sanayileşme ve tarımda makineleşme ile birincil sektördeki istihdam payı düşer; kentlerdeki fabrikalar (ikincil) ve ticaret-ulaşım-eğitim-bankacılık (üçüncül) sektörleri büyür.'),
  ('İnsanların dinlenme, eğlenme, görme, tanıma, sağlık veya spor amacıyla sürekli yaşadıkları yer dışına yaptıkları gezileri ve konaklamaları kapsayan, döviz girdisi nedeniyle "bacasız sanayi" olarak adlandırılan ekonomik etkinlik hangisidir?', 'Turizm', ['Madencilik', 'Tarım', 'Ormancılık'], 'Doğayı sanayi kadar kirletmeden yüksek döviz girdisi, istihdam ve dış ticaret açığını kapatma katkısı sağladığı için turizme "bacasız sanayi" denir.'),
  ('Denizli\'deki Pamukkale travertenleri, kalsiyum bikarbonatça zengin termal suların yüzeye çıktığında içindeki karbondioksit gazının uçması ve kalsiyum karbonatın (kirecin) çökelmesiyle oluşmuş bembeyaz basamaklı bir karstik birikim şeklidir. Geçmişte travertenlerin kararması tehlikesine karşı alınan en etkili koruma önlemi hangisi olmuştur?', 'Travertenlerin hemen üstündeki otellerin yıkılması, araç yolunun kapatılması ve termal suyun kontrollü kanallarla nöbetleşe verilmesi', ['Traverten yüzeyinin her kış beyaz yağlı boya ve kireç harcıyla kaplanması', 'Termal su kaynaklarının betonla kapatılarak su akışının tamamen durdurulması', 'Bölgeye gelen turist sayısının yılda yüz kişiyle sınırlandırılması'], 'Pamukkale\'de suyun otel havuzlarına çekilmesi, kirli atıklar ve ayakkabıyla basılması kararmaya yol açmıştı; UNESCO koruma planıyla oteller kaldırıldı, yol kapatıldı ve su takvimle basamaklara verilerek beyazlık korundu.'),
  ('Çığ afeti; eğimli dağ yamaçlarında biriken kalın kar kütlesinin iç veya dış bir etkiyle (ses, rüzgar, deprem, yeni kar yükü, yol çalışması) dengesini kaybederek hızla vadi tabanına akmasıdır. Türkiye\'de çığ olaylarının Bitlis, Hakkari, Van, Tunceli, Bingöl ve Rize-Artvin iç kesimlerinde yoğunlaşmasının iki temel koşulu nedir?', 'Yüksek eğimli-engebeli çıplak yamaçların varlığı ve yoğun kar yağışı', ['Geniş düz ovaların bulunması ve kışların yağmur şeklinde geçmesi', 'Aktif volkanik sarsıntılar ve kireçli toprak yapısı', 'Denizel ılıman iklim ve gür maki bitki örtüsü'], 'Çığ oluşumu için hem bol kar yağışı hem de karın tutunamayacağı dik eğimli (çoğunlukla ormansız) yüksek yamaçlar gerekir; İç Anadolu kar alsa da düz olduğu için, Akdeniz kıyıları engebeli olsa da kar almadığı için çığ nadirdir; Doğu Anadolu ve Doğu Karadeniz yükseklerinde ikisi birleşir.'),
  ('Dünya üzerinde nüfusun en yoğun olduğu bölgelerden biri olan "Batı Avrupa", diğeri ise "Güneydoğu Asya (Hindistan, Çin doğusu, Japonya, Endonezya)" kuşağıdır. Her ikisi de çok yoğun nüfuslu olmasına rağmen Batı Avrupa\'da nüfus yoğunluğunu yaratan temel ekonomik itici güç aşağıdakilerden hangisidir?', 'Sanayi, ticaret, bilim-teknoloji ve gelişmiş ulaşım ağları', ['Yalnızca emek yoğun çeltik ve çay tarımı', 'Göçebe hayvancılık ve açık maden işletmeciliği', 'Tropikal meyve toplayıcılığı ve balıkçılık'], 'Güneydoğu Asya\'da yoğun nüfusun tarihsel temeli verimli muson/alüvyal ovalarda yoğun tarım (özellikle pirinç) iken —Japonya ve Çin kıyılarında sanayi de eklenmiştir— Batı Avrupa\'da yoğun nüfusun birincil nedeni Sanayi Devrimi, ticaret ve yüksek kentleşmedir.'),
  ('Hollanda, Belçika ve Almanya\'nın kuzeyinde deniz ulaşımı ile iç su yollarının (nehir ve kanalların), demiryollarının ve otoyolların birleştiği "Rotterdam Limanı", Avrupa\'nın en işlek ticaret kapısıdır. Bir limanın gerisinde kalan, limanı besleyen ve limandan mal çeken ekonomik etki alanına coğrafyada ne ad verilir?', 'Hinterland (Art bölge)', ['Falez (Yalıyar)', 'Lagün (Deniz kulağı)', 'Tombolo (Saplı ada)'], 'Bir limanın kara tarafındaki ulaşım, üretim ve tüketim bağlantılarının ulaştığı ticari beslenme alanına "hinterland (art bölge)" denir; Rotterdam\'ın hinterlandı tüm Batı ve Orta Avrupa sanayi kuşağıdır.'),
  ('Kuzey Atlantik Yolu (Batı Avrupa limanları ile Kuzey Amerika\'nın doğu limanları arasındaki hat), dünya deniz ticaretinde ve hava trafiğinde en yoğun güzergahlardan biridir. Bu hattın küresel ulaşımda zirvede yer almasının temel nedeni aşağıdakilerden hangisidir?', 'Dünyanın en gelişmiş iki büyük sanayi, finans, teknoloji ve yüksek gelirli tüketim bölgesini birbirine bağlaması', ['Bu okyanus kuşağında yıl boyunca hiç fırtına ve sis olayının görülmemesi', 'İki kıta arasındaki mesafenin dünyadaki tüm denizlerden daha kısa olması', 'Yalnızca ham petrol ve kereste taşıyan yelkenli gemilerin kullandığı bir rota olması'], 'Batı Avrupa (AB ve İngiltere) ile Kuzey Amerika (ABD ve Kanada doğusu) yüksek sanayi üretimi, sermaye ve alım gücüne sahip olduğundan aralarındaki Kuzey Atlantik deniz ve hava yolu (ve günümüzde Asya-Pasifik hattıyla birlikte) dünyanın en işlek ticaret koridorudur.'),
  ('Türkiye\'nin dünya rezervlerinde yaklaşık %73 payla açık ara birinci sırada yer aldığı; cam, seramik, deterjan, tarım ilacı, yanmaz malzeme, roket yakıtı ve nükleer sanayi gibi yüzlerce alanda kullanılan stratejik maden hangisidir?', 'Bor mineralleri', ['Taş kömürü', 'Fosfat', 'Boksit'], 'Eskişehir (Kırka), Kütahya (Emet), Balıkesir (Bigadiç, Susurluk) ve Bursa (Mustafakemalpaşa) yataklarıyla Türkiye dünya bor rezervlerinin yaklaşık dörtte üçüne sahiptir.'),
  ('Krom madeni paslanmaz çelik üretiminde ve metal kaplamacılığında kullanılan, çeliğe sertlik ve darbe direnci kazandıran önemli bir ferro-alyaj madenidir. Elazığ (Guleman) ve Muğla (Fethiye-Köyceğiz-Dalaman) yörelerinde çıkarılan kromun işlenmesi için kurulan "ferrokrom" tesisleri hangi iki merkezde yer almaktadır?', 'Elazığ ve Antalya', ['Samsun ve Zonguldak', 'Ankara ve Konya', 'Edirne ve Çanakkale'], 'Elazığ\'daki ferrokrom tesisi Guleman kromlarına (hammaddeye yakınlık) ve Keban HES enerjisine; Antalya\'daki ferrokrom tesisi ise Muğla/Toros kromlarının taşınma kolaylığına, suya ve liman ihracat avantajına dayanarak kurulmuştur.'),
  ('Avrupa Birliği (AB), Karadeniz Ekonomik İşbirliği Teşkilatı (KEİ), Kuzey Atlantik Antlaşması Örgütü (NATO) ve Petrol İhraç Eden Ülkeler Örgütü (OPEC) gibi siyasi ve ekonomik bölge sınıflandırmaları zaman içinde yeni ülkelerin katılımıyla genişleyebilmekte veya bazı ülkelerin ayrılmasıyla daralabilmektedir. Hatta bazı örgütler işlevini tamamlayınca tamamen ortadan kalkmaktadır (örneğin Sadabat Paktı veya Varşova Paktı). Bu durum beşeri-siyasi bölgelerin hangi özelliğini gösterir?', 'Sınırlarının esnek, dinamik olduğunu ve uluslararası siyasi-ekonomik çıkarlara göre değişip işlevini yitirebileceğini', ['Sınırlarının yalnızca akarsu su bölümü çizgilerini takip etmek zorunda olduğunu', 'Üye ülkelerin tamamının aynı iklim ve toprak kuşağında yer almasının şart olduğunu', 'Kurulan her siyasi bölgenin sonsuza dek genişleyerek tek dünya devleti olacağını'], 'Siyasi, askeri ve ekonomik bölge sınırları devletlerin kararlarına bağlı beşeri bölgelerdir; Birleşik Krallık\'ın AB\'den çıkması (Brexit) veya Doğu Bloku\'nun dağılmasıyla Varşova Paktı\'nın kapanması bu bölgelerin dinamik ve değişken doğasını kanıtlar.'),
  ('Kurak ve yarı kurak bölgelerde rüzgar erozyonunu önlemek, kar savrulmasını azaltmak ve tarım alanlarındaki toprak nemini korumak amacıyla tarla kenarlarına hakim rüzgar yönüne dik olarak dikilen ağaç sıralarına ne ad verilir?', 'Rüzgar kıran (rüzgar perdesi) kuşakları', ['Seki (taraça) basamakları', 'Nadas parselleri', 'Drenaj kanalları'], 'Karapınar (Konya) erozyon önleme sahasında da başarıyla uygulandığı gibi, rüzgar hızını keserek toprağın uçmasını ve aşırı buharlaşmayı azaltan ağaç şeritlerine rüzgar perdesi / rüzgar kıran denir (taraça/seki ise eğimli yamaçlarda su erozyonunu önlemek için yapılan basamaklardır).'),
  ('Akdeniz iklim kuşağında kışın ılık ve yağışlı dönemde gelişen, yaz kuraklığına dayanabilmek için yaprakları sert, cilalı, tüylü veya küçük olan defne, zakkum, kocayemiş, mersin, keçiboynuzu ve yabani zeytin (delice) gibi çalı-ağaççık türlerinin oluşturduğu bitki topluluğu hangisidir?', 'Maki', ['Tundra', 'Savan', 'Tayga'], 'Defne, mersin, kocayemiş, keçiboynuzu, zakkum, sakız ve kermez meşesi gibi her dem yeşil, kurakçıl sert yapraklı Akdeniz çalı formasyonuna maki denir.'),
];
